window.GLOSSARY=[{"t":"\"Longitude east, UTC least; longitude west, UTC best\"","d":"LMT = UTC + d.long/15 (east); LMT = UTC − d.long/15 (west).","s":"Nav 5","ch":"Time","sec":"Conversions","h":"chapters/nav-05.html#n-conversions"},{"t":"Above 8 km reversal","d":"density greater over the equator.","s":"Met 4","ch":"Air Density","sec":"Latitudinal variation (p.39)","h":"chapters/met-04.html#n-latitudinal-variation-p-39"},{"t":"Absolute ceiling","d":"rate of climb zero; service ceiling: ~100 ft/min.","s":"Nav 15","ch":"Performance","sec":"Cruise, ceiling, descent, glide","h":"chapters/nav-15.html#n-cruise-ceiling-descent-glide"},{"t":"Absolute humidity","d":"actual mass of WV per volume of air (g/m³).","s":"Met 5","ch":"Humidity","sec":"Terms (p.41–42)","h":"chapters/met-05.html#n-terms-p-41-42"},{"t":"Absolute zero","d":"the lowest possible temperature, same for all substances; molecular motion almost stops. 0 K = −273.16°C (book wording \"1K = −273.16°C\").","s":"Met 3","ch":"Temperature","sec":"Scales (p.27)","h":"chapters/met-03.html#n-scales-p-27"},{"t":"AC","d":"light to moderate; severe possible over mountains.","s":"Met 12","ch":"Ice Accretion","sec":"Icing by cloud (p.108)","h":"chapters/met-12.html#n-icing-by-cloud-p-108"},{"t":"Acceleration/deceleration","d":"max on E/W headings, nil on N/S. APDE: Acceleration → apparent turn towards the nearer Pole; Deceleration → towards the Equator. NH: accelerating on west, card turns clockwise, under-reads, shows a turn to the right/north.","s":"Nav 8","ch":"Magnetism and Compasses","sec":"Errors due to dip (direct-reading compass)","h":"chapters/nav-08.html#n-errors-due-to-dip-direct-reading-compass"},{"t":"Acceptance","d":"the first ATS unit checks format and data conventions, completeness and accuracy, makes it acceptable if needed and indicates acceptance to the originator.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Submission","h":"chapters/nav-16.html#n-submission"},{"t":"Active spells and breaks","d":"break = trough shifts to the Himalayan foothills → rain drops over the plains, pressure rises, heavy rain over the foothills (sub-Himalayan WB, Nepal, Bhutan) → floods in NE India and Bihar; strong surface westerlies over E UP/Bihar; pre-monsoon-type weather with dust haze; hot and humid.","s":"Met 19","ch":"Climatology of India","sec":"SW monsoon (Jun–Sep) (p.175–180)","h":"chapters/met-19.html#n-sw-monsoon-jun-sep-p-175-180"},{"t":"ADF on an RBI","d":"needle shows relative bearing; QDM = relative bearing + magnetic heading; QDR = QDM ± 180; QTE = QDR ± variation at the aircraft.","s":"Nav 13","ch":"In-flight Navigation","sec":"Fixes and position lines","h":"chapters/nav-13.html#n-fixes-and-position-lines"},{"t":"Adiabatic change","d":"no heat exchanged with the surroundings. Isothermal change: at constant temperature.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Physical terms (2-3)","h":"chapters/hb-01.html#n-physical-terms-2-3"},{"t":"Adiabatic process","d":"no heat exchange. Rising parcel → lower pressure → expands → cools (work done from internal energy); sinking parcel → compressed → warms. Adiabatic processes largely determine the vertical temperature distribution.","s":"Met 9","ch":"Stability and Instability","sec":"Processes (p.87)","h":"chapters/met-09.html#n-processes-p-87"},{"t":"Advection fog","d":"warm moist air moves over a colder surface (land or sea) whose temperature is below the air's dew point. Land and sea; any time of day or night. Coastal Bengal and Orissa winter fogs = advection + radiation; Brahmaputra valley, Sundarbans, coastal belts and peninsular hills.","s":"Met 7","ch":"Visibility and Fog","sec":"Other fogs (p.72)","h":"chapters/met-07.html#n-other-fogs-p-72"},{"t":"Aerodrome warning","d":"by AMOs, weather affecting aircraft on the ground and facilities (picketing, mooring); validity ≤ 4 h. Wind ≥ 30 kt, or direction of a 20-kt wind changing by 45°; squall, TC, DS, SS, TS, hail, frost, snow, hoar frost/rime, freezing precipitation, rising sand/dust, VA, tsunami.","s":"Met 21","ch":"Met Services for Aviation","sec":"Warnings (p.200)","h":"chapters/met-21.html#n-warnings-p-200"},{"t":"Aerodynamic centre (AC)","d":"the point about which the pitching moment stays constant with AoA; the point where all changes of lift effectively act. Below about 0.4 Mach it is at 25% chord for any aerofoil, whatever its camber, thickness or AoA. Calculations use the fixed AC instead of the moving CP.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Centre of pressure and aerodynamic centre (2-10)","h":"chapters/hb-01.html#n-centre-of-pressure-and-aerodynamic-centre-2-10"},{"t":"Aerofoil","d":"a shape that produces lift. Chord line: straight line from leading edge (LE) to trailing edge (TE); chord: its length. Root chord Cr, tip chord Ct, mean chord c̄. Span b: tip to tip. Wing area S = chord × span.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Definitions (2-9)","h":"chapters/hb-01.html#n-definitions-2-9"},{"t":"Aeroplane reference field length","d":"minimum length at MTOM, sea level, ISA, nil wind, zero slope.","s":"Nav 15","ch":"Performance","sec":"Declared distances","h":"chapters/nav-15.html#n-declared-distances"},{"t":"Aft CG","d":"less stable, lighter controls, lower stall speed but risk of stall/spin (flat spin) recovery problems, overstress risk; rapid rotation on take-off; range and endurance reduced if grossly outside; glide hard to sustain.","s":"Nav 14","ch":"Mass and Balance","sec":"CG position effects","h":"chapters/nav-14.html#n-cg-position-effects"},{"t":"Air mass","d":"large body of air (thousands of km²) with nearly uniform horizontal and vertical distribution of temperature (density) and moisture. Moves with the wind and is modified by the surfaces it crosses.","s":"Met 14","ch":"Air Masses, Fronts and WDs","sec":"Air masses (p.129–130)","h":"chapters/met-14.html#n-air-masses-p-129-130"},{"t":"Air pocket","d":"local up- or downdraught from warm/cool pockets or high/low pressure.","s":"Met 13","ch":"Thunderstorms","sec":"Air pockets, downbursts, microbursts (p.121–123)","h":"chapters/met-13.html#n-air-pockets-downbursts-microbursts-p-121-123"},{"t":"Air-mass (heat) TS","d":"intense surface heating + convergence in a low; also cold air over a warm sea. Random, relatively weak; afternoons over plains; night/morning in valleys and hills.","s":"Met 13","ch":"Thunderstorms","sec":"Types (p.112–113)","h":"chapters/met-13.html#n-types-p-112-113"},{"t":"AIREP / PIREP","d":"with air-ground data link, automated observations every 15 min en route and every 30 s during climb-out for the first 10 min. Special observations whenever SIGMET-criteria weather is met; wind shear, icing, turbulence passed to ATS ASAP; volcanic activity report submitted to the AMO on arrival → MWO of that region.","s":"Met 21","ch":"Met Services for Aviation","sec":"Observations and reports","h":"chapters/met-21.html#n-observations-and-reports"},{"t":"AIRMET","d":"SIGMET-type information for low-level flights, issued by the MWO for an FIR or sub-area (prepared by AMOs, exchanged with adjacent FIRs). GAMET: area forecast in abbreviated plain language for low-level flights.","s":"Met 21","ch":"Met Services for Aviation","sec":"SIGMET (p.199)","h":"chapters/met-21.html#n-sigmet-p-199"},{"t":"Albedo","d":"reflected ÷ incident radiation = reflecting power of the earth (~30%).","s":"Met 3","ch":"Temperature","sec":"Heat budget and albedo (p.31–32)","h":"chapters/met-03.html#n-heat-budget-and-albedo-p-31-32"},{"t":"Alternate aerodrome","d":"where an aircraft may go when it is impossible or inadvisable to proceed to or land at the intended aerodrome:","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Definitions (Annex 2 / Doc 4444)","h":"chapters/nav-16.html#n-definitions-annex-2-doc-4444"},{"t":"Alternate static source","d":"inside the cockpit (unpressurised aircraft only) or outside; selected by the pilot (switch) if the main source is blocked by ice etc. Cabin pressure is lower than outside (airflow over the cabin), so on the alternate source:","s":"Nav 17","ch":"Air Data Systems","sec":"The pitot-static system","h":"chapters/nav-17.html#n-the-pitot-static-system"},{"t":"Altimeter","d":"an aneroid barometer graduated in altitude, with a sub-scale for the pressure setting.","s":"Met 2","ch":"Atmospheric Pressure","sec":"Measurement (p.15)","h":"chapters/met-02.html#n-measurement-p-15"},{"t":"Altimeter","d":"rapid height changes beat the capsule's response (hysteresis); plus temperature errors (colder than ISA → reads too high). Don't trust it for terrain clearance.","s":"Met 16","ch":"CAT and Mountain Waves","sec":"Turbulence and altimetry (p.151)","h":"chapters/met-16.html#n-turbulence-and-altimetry-p-151"},{"t":"Altitude","d":"vertical distance from MSL. Height: from a specified datum (e.g. ground). Elevation: of a point on the earth's surface, from MSL.","s":"Met 2","ch":"Atmospheric Pressure","sec":"Altimetry definitions (p.17)","h":"chapters/met-02.html#n-altimetry-definitions-p-17"},{"t":"Altitude","d":"higher → less dense. Temperature: warmer → less dense. Humidity: humid air is lighter (minor factor).","s":"Met 4","ch":"Air Density","sec":"Factors affecting density (p.38)","h":"chapters/met-04.html#n-factors-affecting-density-p-38"},{"t":"Ambient temperature","d":"temperature of the surroundings.","s":"Met 3","ch":"Temperature","sec":"Definitions (p.28)","h":"chapters/met-03.html#n-definitions-p-28"},{"t":"Ana (unstable) warm front","d":"CU/CB embedded in the layer cloud → bursts of heavy rain.","s":"Met 14","ch":"Air Masses, Fronts and WDs","sec":"Warm front (p.133–134)","h":"chapters/met-14.html#n-warm-front-p-133-134"},{"t":"Ana cold front","d":"slope ~1:50, > 30 kt; warm air rises, unstable; CU/CB, violent TS, hail, short showers in a 100–150 km belt; sky clears rapidly after passage; isolated showers behind.","s":"Met 14","ch":"Air Masses, Fronts and WDs","sec":"Cold front (p.132–133)","h":"chapters/met-14.html#n-cold-front-p-132-133"},{"t":"Anabatic","d":"daytime upslope wind (heated slope); weak, masked by convection; stronger when funnelled = valley wind; helped by sea breeze on coasts.","s":"Met 6","ch":"Winds","sec":"Local winds (p.55–58)","h":"chapters/met-06.html#n-local-winds-p-55-58"},{"t":"Aneroid barometer","d":"less accurate but convenient, widely used.","s":"Met 2","ch":"Atmospheric Pressure","sec":"Measurement (p.15)","h":"chapters/met-02.html#n-measurement-p-15"},{"t":"Angle of climb","d":"between horizontal and flight path. Angle of attack: between relative airflow and chord. Climb gradient = height gained ÷ horizontal distance × 100%.","s":"Nav 15","ch":"Performance","sec":"Terms","h":"chapters/nav-15.html#n-terms"},{"t":"Angle of incidence","d":"between the chord line and the aircraft's longitudinal datum (fixed). Angle of attack: between the chord line and the relative airflow (varies).","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Definitions (2-9)","h":"chapters/hb-01.html#n-definitions-2-9"},{"t":"Apparent solar day","d":"between two transits of the true sun (varies 23 h 44 min – 24 h 14 min, because the orbit is elliptical, not because rotation varies).","s":"Nav 1","ch":"The Solar System","sec":"Year and day","h":"chapters/nav-01.html#n-year-and-day"},{"t":"ARFOR","d":"area forecast (coded/tabular): upper winds/temps, sig weather, cloud, freezing level, turbulence, icing, jet, tropopause, max wind, wind shear, warnings.","s":"Met 21","ch":"Met Services for Aviation","sec":"Aviation forecasts (p.197–199)","h":"chapters/met-21.html#n-aviation-forecasts-p-197-199"},{"t":"Arm (balance arm)","d":"distance from the datum to a mass's CG. Moment = mass × arm. CG = total moment ÷ total mass.","s":"Nav 14","ch":"Mass and Balance","sec":"Definitions","h":"chapters/nav-14.html#n-definitions"},{"t":"AS, NS","d":"supercooled drops + ice → light to moderate.","s":"Met 12","ch":"Ice Accretion","sec":"Icing by cloud (p.108)","h":"chapters/met-12.html#n-icing-by-cloud-p-108"},{"t":"ASI compressibility error","d":"air brought to rest in the pitot tube is compressed, raising pitot pressure → ASI over-reads (IAS too high). Negligible at or below 300 kt TAS and ignored.","s":"Nav 17","ch":"Air Data Systems","sec":"Errors specific to the ASI and VSI","h":"chapters/nav-17.html#n-errors-specific-to-the-asi-and-vsi"},{"t":"ASI density error","d":"flying from high to low density, the ASI under-reads (dynamic pressure = ½ρV²). For the same IAS, TAS increases as density falls, and vice versa.","s":"Nav 17","ch":"Air Data Systems","sec":"Errors specific to the ASI and VSI","h":"chapters/nav-17.html#n-errors-specific-to-the-asi-and-vsi"},{"t":"ASI principle","d":"pitot (total) pressure = ½ ρ V² + S; ASI measures total − static = dynamic pressure. By Bernoulli the total pressure in a streamline flow is the same everywhere, so the pitot head can sit anywhere in the flow; the static source must sense true ambient pressure.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Density and pressures (2-5)","h":"chapters/hb-01.html#n-density-and-pressures-2-5"},{"t":"ATIS","d":"continuous broadcast of half-hourly current weather at important aerodromes.","s":"Met 21","ch":"Met Services for Aviation","sec":"Exchange of met messages (p.201)","h":"chapters/met-21.html#n-exchange-of-met-messages-p-201"},{"t":"Atlantic Niño","d":"Atlantic warming weakens the monsoon; cooling strengthens it.","s":"Met 30","ch":"Appendices: Scales, Terms and Monsoon Drivers","sec":"G. Other systems influencing the SW monsoon","h":"chapters/met-30.html#n-g-other-systems-influencing-the-sw-monsoon"},{"t":"ATS reporting office","d":"unit that receives reports on ATS and flight plans submitted before departure.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Definitions (Annex 2 / Doc 4444)","h":"chapters/nav-16.html#n-definitions-annex-2-doc-4444"},{"t":"Avoidance","d":"whatever the course, strong wind from port means the centre is ahead → alter course until the wind is from starboard and weakening.","s":"Met 18","ch":"Tropical Systems","sec":"Indian cyclones (p.162–163)","h":"chapters/met-18.html#n-indian-cyclones-p-162-163"},{"t":"Axis","d":"line of maximum speed; core = tube around it. Speed along the axis is not uniform: centres of maximum speed = jet streaks (located near ridges in a wavy jet). Where speed drops below 60 kt = breaks. Jets can split or merge.","s":"Met 15","ch":"Jet Streams","sec":"Definition (p.140)","h":"chapters/met-15.html#n-definition-p-140"},{"t":"B — Barometric","d":"sub-scale differs from the actual pressure at the point → wrong indication.","s":"Nav 18","ch":"Altimeter","sec":"Errors — \"BLIP PBT\"","h":"chapters/nav-18.html#n-errors-blip-pbt"},{"t":"B — Blockage","d":"indicates a constant altitude in climb or descent; the pointer freezes (static blocked at 9000 ft, aircraft at 10 000 ft → reads 9000 ft).","s":"Nav 18","ch":"Altimeter","sec":"Errors — \"BLIP PBT\"","h":"chapters/nav-18.html#n-errors-blip-pbt"},{"t":"Backing","d":"direction changes anticlockwise (090 → 060). Veering = clockwise (060 → 090). Example: 310° → 020° veers; 270° → 250° backs.","s":"Met 6","ch":"Winds","sec":"Backing and veering, Buys Ballot (p.47)","h":"chapters/met-06.html#n-backing-and-veering-buys-ballot-p-47"},{"t":"Balanced field length","d":"V1 chosen so that ASDR = TODR; the shortest field length for given conditions, allowing the maximum take-off mass. Raising V1 lowers TODR and raises ASDR.","s":"Nav 15","ch":"Performance","sec":"Declared distances","h":"chapters/nav-15.html#n-declared-distances"},{"t":"Barograph","d":"continuous record (daily or weekly).","s":"Met 2","ch":"Atmospheric Pressure","sec":"Measurement (p.15)","h":"chapters/met-02.html#n-measurement-p-15"},{"t":"Basic empty mass (BEM)","d":"aeroplane + unusable fuel and fluids, engine/APU oil, fire extinguishers, pyrotechnics, emergency oxygen, supplementary electronics (from the latest weighing schedule).","s":"Nav 14","ch":"Mass and Balance","sec":"Mass terms","h":"chapters/nav-14.html#n-mass-terms"},{"t":"Bernoulli's theorem","d":"in steady streamline flow of an ideal fluid, pressure + kinetic + potential energy = constant; for aircraft, P + ½ ρ V² = constant. Where flow speeds up, static pressure falls (total pressure unchanged).","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Streamline flow and lift theories (2-6 to 2-7)","h":"chapters/hb-01.html#n-streamline-flow-and-lift-theories-2-6-to-2-7"},{"t":"Bishop's ring","d":"faint whitish ring, bluish inside, reddish-brown outside, radius ~22°; diffraction by fine dust high in the atmosphere (often volcanic).","s":"Met 10","ch":"Optical Phenomena","sec":"Other phenomena (p.97–98)","h":"chapters/met-10.html#n-other-phenomena-p-97-98"},{"t":"Black body","d":"a body that emits radiation (at its temperature) over a wide range of wavelengths.","s":"Met 3","ch":"Temperature","sec":"Insolation and radiation laws (p.30)","h":"chapters/met-03.html#n-insolation-and-radiation-laws-p-30"},{"t":"Blocking anticyclone","d":"near-stationary high that blocks migratory cyclones.","s":"Met 2","ch":"Atmospheric Pressure","sec":"Pressure patterns (p.21–22) (isobars at 2 hPa)","h":"chapters/met-02.html#n-pressure-patterns-p-21-22-isobars-at-2-hpa"},{"t":"Bora","d":"cold katabatic, Yugoslavia/NE Italy → Adriatic. Mistral: katabatic down the Rhône valley (France) to the Gulf of Lyons.","s":"Met 6","ch":"Winds","sec":"Named winds (p.61–62)","h":"chapters/met-06.html#n-named-winds-p-61-62"},{"t":"Buran (Purga with snow)","d":"strong NE wind, Russia/central Asia, winter. Chinook: warm dry westerly, east of the Rockies.","s":"Met 6","ch":"Winds","sec":"Named winds (p.61–62)","h":"chapters/met-06.html#n-named-winds-p-61-62"},{"t":"Buys Ballot's law","d":"in the NH, stand with your back to the wind — low pressure is on your left, high on the right. Opposite in SH.","s":"Met 6","ch":"Winds","sec":"Backing and veering, Buys Ballot (p.47)","h":"chapters/met-06.html#n-backing-and-veering-buys-ballot-p-47"},{"t":"Calvus","d":"CB without cirrus top yet. Capillatus: CB with a distinct anvil → SH, TS, squalls, hail, virga.","s":"Met 8","ch":"Vertical Motion and Clouds","sec":"Species (p.83)","h":"chapters/met-08.html#n-species-p-83"},{"t":"Cambered aerofoil","d":"as AoA increases the suction peak grows and moves forward, TR grows and CP moves forward (nose-up, destabilising); CP is furthest forward at CLmax; at the stall TR drops and CP moves back. In normal use CP stays around 20–30% of chord.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Centre of pressure and aerodynamic centre (2-10)","h":"chapters/hb-01.html#n-centre-of-pressure-and-aerodynamic-centre-2-10"},{"t":"Carburettor icing","d":"pressure drop through the venturi (choke) and past the throttle butterfly → adiabatic cooling, plus fuel evaporation cooling → ice even in clear air at +30°C. Serious range +30°C to −10°C. Below −10°C negligible unless liquid water present; unlikely when RH < 60%.","s":"Met 12","ch":"Ice Accretion","sec":"Engine icing (p.109)","h":"chapters/met-12.html#n-engine-icing-p-109"},{"t":"Cardinal points","d":"N, S, E, W.","s":"Nav 2","ch":"The Earth","sec":"Longitude and meridians","h":"chapters/nav-02.html#n-longitude-and-meridians"},{"t":"Castellanus","d":"CI/CC/AC with turret-like cumuliform tops in lines → mid-level instability.","s":"Met 8","ch":"Vertical Motion and Clouds","sec":"Species (p.83)","h":"chapters/met-08.html#n-species-p-83"},{"t":"CAT","d":"bumpiness at high altitude in cloud-free air (or in cirrus), where air moving at very different speeds meets.","s":"Met 16","ch":"CAT and Mountain Waves","sec":"Clear Air Turbulence (p.147–148)","h":"chapters/met-16.html#n-clear-air-turbulence-p-147-148"},{"t":"CB","d":"light to severe up to the −20°C level; below that severe icing not significant.","s":"Met 12","ch":"Ice Accretion","sec":"Icing by cloud (p.108)","h":"chapters/met-12.html#n-icing-by-cloud-p-108"},{"t":"CB/TS coverage","d":"ISOL < 50% · OCNL 50–75% · FRQ > 75%.","s":"Met 30","ch":"Appendices: Scales, Terms and Monsoon Drivers","sec":"D. Miscellaneous terms","h":"chapters/met-30.html#n-d-miscellaneous-terms"},{"t":"Ceiling","d":"height of the lowest layer below 6000 m (20,000 ft) covering more than half the sky (≥ 5/8).","s":"Met 8","ch":"Vertical Motion and Clouds","sec":"Reporting (p.80–82)","h":"chapters/met-08.html#n-reporting-p-80-82"},{"t":"Celsius","d":"ice 0°C, boiling 100°C (international, aviation, science). Fahrenheit: 32°F and 212°F (a few English-speaking countries).","s":"Met 3","ch":"Temperature","sec":"Scales (p.27)","h":"chapters/met-03.html#n-scales-p-27"},{"t":"Centre of pressure (CP)","d":"the point through which the total reaction acts; its position depends on camber, CL and angle of attack. The book treats TR as roughly perpendicular to the chord.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Centre of pressure and aerodynamic centre (2-10)","h":"chapters/hb-01.html#n-centre-of-pressure-and-aerodynamic-centre-2-10"},{"t":"CG","d":"point through which the weight acts (vertically, along the gravity vector); point of balance; the point the aircraft manoeuvres about and the three axes pass through. Must stay within forward and aft (and lateral) limits — the CG range/envelope.","s":"Nav 14","ch":"Mass and Balance","sec":"Definitions","h":"chapters/nav-14.html#n-definitions"},{"t":"Changes","d":"all changes to an IFR flight plan or a controlled VFR flight must be reported as soon as practicable; for other VFR flights, significant changes. Incorrect fuel endurance or persons on board at departure is a significant change.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Adherence, changes and deviations","h":"chapters/nav-16.html#n-adherence-changes-and-deviations"},{"t":"Character of echoes","d":"EYE (eye wall of a TC), SPRL BAND (spiral band), SQL LN (squall line ≥ 60 km long, length:width ≈ 10:1), BRKN LN broken line, SLD area fully covered, BRKN 4/8–7/8 covered, SCT 1/8–4/8, WDLY SCT < 1/8, ISLTD isolated solid echo, ECHO ALOFT seen only at elevations above the beam width.","s":"Met 27","ch":"Radar Report, SIGMET and Satellite Bulletin","sec":"RAREP — radar report (p.255–257)","h":"chapters/met-27.html#n-rarep-radar-report-p-255-257"},{"t":"CI, CS, CC","d":"ice crystals → negligible icing.","s":"Met 12","ch":"Ice Accretion","sec":"Icing by cloud (p.108)","h":"chapters/met-12.html#n-icing-by-cloud-p-108"},{"t":"Circular motion","d":"angular velocity ω = v / r; centripetal acceleration = v² / r; centripetal force = m v² / r = W v² / (g r). Moment of inertia I = Σ m r². Angular momentum = I ω.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Laws (2-4)","h":"chapters/hb-01.html#n-laws-2-4"},{"t":"Circulation (Magnus effect)","d":"a non-spinning cylinder has equal flow above and below — no lift. Spinning it speeds the flow on one side and slows it on the other, moving the stagnation points, so pressure is lower on the fast side → lift. A rough surface drags more air round → more circulation → more lift (golf ball dimples).","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Streamline flow and lift theories (2-6 to 2-7)","h":"chapters/hb-01.html#n-streamline-flow-and-lift-theories-2-6-to-2-7"},{"t":"Clearway","d":"area beyond the runway (under aerodrome control) over which the initial climb may be made; ≤ half TORA long; at least 75 m each side of the extended centre line (instrument runway); up-slope ≤ 1.25%; obstacle-free; may include the stopway; within the airport boundary; its centre line is imaginary, shown on diagrams/charts. Counts in TODA.","s":"Nav 15","ch":"Performance","sec":"Declared distances","h":"chapters/nav-15.html#n-declared-distances"},{"t":"Climb","d":"find the distance gone in the climb; subtract from the stage length → distance left in cruise.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Principles of fuel planning (p.278)","h":"chapters/nav-16.html#n-principles-of-fuel-planning-p-278"},{"t":"Cloud","d":"visible aggregate of water droplets or ice particles, formed by adiabatic lifting and cooling until WV condenses (or deposits directly as ice). Height of condensation = lifting condensation level (LCL).","s":"Met 8","ch":"Vertical Motion and Clouds","sec":"Clouds: formation and classification (p.77)","h":"chapters/met-08.html#n-clouds-formation-and-classification-p-77"},{"t":"Cloud","d":"BKN/OVC base passes 30, 60, 150, 300, 450 m; amount below 450 m changes between SKC/FEW/SCT and BKN/OVC.","s":"Met 25","ch":"METAR, SPECI and TREND","sec":"SPECI criteria (p.230–231) — deterioration at once, improvement after 10 min","h":"chapters/met-25.html#n-speci-criteria-p-230-231-deterioration-at-once-improvement-after-10-min"},{"t":"Cloud base steps","d":"30 m (100 ft) up to 3000 m; 300 m above. Amounts FEW 1–2, SCT 3–4, BKN 5–7, OVC 8 octas; SKC clear; NSC no significant cloud. Layers: lowest regardless of amount; next if ≥ 3/8; next if ≥ 5/8; CB always. Height in hundreds of feet: SCT015 = 3–4/8 at 1500 ft; FEW020CB. Sky obscured: VVhhh (vertical visibility).","s":"Met 25","ch":"METAR, SPECI and TREND","sec":"Reporting rules","h":"chapters/met-25.html#n-reporting-rules"},{"t":"Cloud burst","d":"very heavy rain/showers over an area in a short time. Flash flood: sudden rise of rivers/streams.","s":"Met 11","ch":"Precipitation","sec":"Snow, sleet and terms (p.104)","h":"chapters/met-11.html#n-snow-sleet-and-terms-p-104"},{"t":"Cloud discharge (sheet lightning)","d":"within the cloud. Air discharge: cloud to air.","s":"Met 10","ch":"Optical Phenomena","sec":"Atmospheric electricity and lightning (p.99–100)","h":"chapters/met-10.html#n-atmospheric-electricity-and-lightning-p-99-100"},{"t":"Cloud of operational significance","d":"base below 1500 m (5000 ft) or below the highest minimum sector altitude, whichever is greater (or any CB/TCU).","s":"Met 8","ch":"Vertical Motion and Clouds","sec":"Reporting (p.80–82)","h":"chapters/met-08.html#n-reporting-p-80-82"},{"t":"Clouds","d":"by day they reflect sunlight (thin cirrostratus cuts some; thick low cloud/fog may cut all) → cooler days; by night they absorb outgoing radiation and their bases radiate back → cloudy nights are warmer.","s":"Met 3","ch":"Temperature","sec":"Diurnal variation of surface temperature (p.32–33)","h":"chapters/met-03.html#n-diurnal-variation-of-surface-temperature-p-32-33"},{"t":"CO₂","d":"from burning fuel/wood; high in industrial areas, negligible over poles and at height; large amounts dissolved in oceans; plants absorb CO₂, release O₂.","s":"Met 1","ch":"Atmosphere","sec":"CO₂, ozone and particles (p.3)","h":"chapters/met-01.html#n-co-ozone-and-particles-p-3"},{"t":"CODAR","d":"upper-air report from an aircraft (not a weather-reconnaissance aircraft), figure code.","s":"Met 21","ch":"Met Services for Aviation","sec":"Aviation forecasts (p.197–199)","h":"chapters/met-21.html#n-aviation-forecasts-p-197-199"},{"t":"CODAR","d":"aircraft upper-air report; WINTEM = forecast wind/temp; ROBEX = outside India.","s":"Met 21","ch":"Met Services for Aviation","sec":"Exam traps","h":"chapters/met-21.html#n-exam-traps"},{"t":"Col","d":"between two highs and two lows; uniform pressure, light variable winds, mixed weather.","s":"Met 2","ch":"Atmospheric Pressure","sec":"Pressure patterns (p.21–22) (isobars at 2 hPa)","h":"chapters/met-02.html#n-pressure-patterns-p-21-22-isobars-at-2-hpa"},{"t":"Col","d":"two lows and two highs.","s":"Met 2","ch":"Atmospheric Pressure","sec":"Exam traps","h":"chapters/met-02.html#n-exam-traps"},{"t":"Cold anticyclone","d":"forms over cold ground behind a departing cyclone; subsidence later warms it.","s":"Met 2","ch":"Atmospheric Pressure","sec":"Pressure patterns (p.21–22) (isobars at 2 hPa)","h":"chapters/met-02.html#n-pressure-patterns-p-21-22-isobars-at-2-hpa"},{"t":"Cold occlusion","d":"air behind the cold front colder than the cool air ahead → undercuts and lifts both; warm-front weather then cold-front showers; common in summer.","s":"Met 14","ch":"Air Masses, Fronts and WDs","sec":"Occlusions and others (p.134–135)","h":"chapters/met-14.html#n-occlusions-and-others-p-134-135"},{"t":"Compass direction (°C)","d":"measured from compass north — where the aircraft's compass actually points, disturbed by the aircraft's own magnetic fields.","s":"Nav 6","ch":"Compass and Directions","sec":"Three norths","h":"chapters/nav-06.html#n-three-norths"},{"t":"Compression (ellipticity) ≈ 1/297","d":"(major axis − minor axis) / major axis. Satellite geodesy shows a slight pear shape, more mass in the SH.","s":"Nav 2","ch":"The Earth","sec":"Shape and size","h":"chapters/nav-02.html#n-shape-and-size"},{"t":"Computer","d":"calculates TAS, Mach number, corrected static pressure and corrected OAT; originates correction signals to transducers; drives displays; feeds navigation computers; controls pressurisation; gives inputs to the AFCS and engine fuel control units.","s":"Nav 17","ch":"Air Data Systems","sec":"Air data system","h":"chapters/nav-17.html#n-air-data-system"},{"t":"Conduction","d":"molecule-to-molecule by contact; important very close to the ground. (Air is a poor conductor.)","s":"Met 3","ch":"Temperature","sec":"Heat transfer (p.29–30)","h":"chapters/met-03.html#n-heat-transfer-p-29-30"},{"t":"Contour (isohypse)","d":"line of equal height of a pressure surface; acts like an isobar.","s":"Met 2","ch":"Atmospheric Pressure","sec":"Contours and thickness (p.16)","h":"chapters/met-02.html#n-contours-and-thickness-p-16"},{"t":"Convection","d":"hot fluid bodily moves to the colder part. Free convection = intense solar heating; forced convection = topography/mechanical lifting. >70% of earth is water → convection important.","s":"Met 3","ch":"Temperature","sec":"Heat transfer (p.29–30)","h":"chapters/met-03.html#n-heat-transfer-p-29-30"},{"t":"Convection (thermals)","d":"from ground heating; used by gliders; bumpiness; CU/CB with strong up- and downdraughts.","s":"Met 8","ch":"Vertical Motion and Clouds","sec":"Vertical motion (p.75–76)","h":"chapters/met-08.html#n-vertical-motion-p-75-76"},{"t":"Convective cloud","d":"sharp-edged echoes; blurring of edges = first sign of decay; squall lines show as line echoes. Exceptionally intense echo or top reaching about −40 °C level → CB.","s":"Met 22","ch":"Weather Radar and Met Satellites","sec":"Cloud echoes (p.208–209)","h":"chapters/met-22.html#n-cloud-echoes-p-208-209"},{"t":"Convergence","d":"net horizontal inflow → ascent near the ground (aloft, can go up or down below the tropopause). Lows, cyclones, depressions, troughs → bad weather, better visibility (except in precipitation).","s":"Met 8","ch":"Vertical Motion and Clouds","sec":"Convergence and divergence (p.76–78)","h":"chapters/met-08.html#n-convergence-and-divergence-p-76-78"},{"t":"Convergence","d":"zero on the chart; correct only at the equator.","s":"Nav 3","ch":"Projections","sec":"Mercator (direct)","h":"chapters/nav-03.html#n-mercator-direct"},{"t":"Convergency","d":"the angle of inclination between two meridians at a given latitude = the change of great-circle track between them. Zero at the equator, equal to d.long at the poles; varies as sin latitude.","s":"Nav 4","ch":"Convergency","sec":"Definitions","h":"chapters/nav-04.html#n-definitions"},{"t":"Conversion angle (CA)","d":"angle between the GC and the RL at either end = ½ convergency (maximum near the poles).","s":"Nav 4","ch":"Convergency","sec":"Definitions","h":"chapters/nav-04.html#n-definitions"},{"t":"Crepuscular rays","d":"dark bluish streaks radiating from the sun = shadows of clouds at/below the horizon.","s":"Met 10","ch":"Optical Phenomena","sec":"Other phenomena (p.97–98)","h":"chapters/met-10.html#n-other-phenomena-p-97-98"},{"t":"Cumuliform","d":"CC, AC some turbulence; fair-weather CU and SC bumpy; CU, TCU, CB serious: severe turbulence, hail, up/downdraughts, gusts, icing, lightning. Turbulence up to 10–20 km around an active CB. Avoid landing/take-off in TS squalls. Hail can fall in clear air under the anvil.","s":"Met 8","ch":"Vertical Motion and Clouds","sec":"Flying conditions (p.81–82)","h":"chapters/met-08.html#n-flying-conditions-p-81-82"},{"t":"Current flight plan","d":"including changes brought about by subsequent clearances.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Definitions (Annex 2 / Doc 4444)","h":"chapters/nav-16.html#n-definitions-annex-2-doc-4444"},{"t":"Cyclostrophic","d":"strongly curved flow where Coriolis is negligible; PGF balances centripetal (ρV²/r). Good near the centre of a tropical revolving storm or a tornado (e.g. 2000 ft wind in an intense TRS).","s":"Met 6","ch":"Winds","sec":"Cyclostrophic, gradient, isallobaric, inertial winds (p.50–51)","h":"chapters/met-06.html#n-cyclostrophic-gradient-isallobaric-inertial-winds-p-50-51"},{"t":"d.lat (ch.lat)","d":"same hemisphere → subtract; opposite hemispheres → add (40°N to 30°S = 70°).","s":"Nav 2","ch":"The Earth","sec":"Change of latitude and longitude","h":"chapters/nav-02.html#n-change-of-latitude-and-longitude"},{"t":"d.long (ch.long)","d":"same hemisphere → subtract; opposite hemispheres → add, but if the sum exceeds 180° take 360° − sum (go the short way across 180°). Direction: anticlockwise seen from above N pole = east, clockwise = west.","s":"Nav 2","ch":"The Earth","sec":"Change of latitude and longitude","h":"chapters/nav-02.html#n-change-of-latitude-and-longitude"},{"t":"Datum","d":"point on the longitudinal axis (or its extension) from which all arms are measured (set by the manufacturer; may be ahead of the nose; small helicopters often 100 in ahead of the rotor mast to keep arms positive). Aft of datum = positive arm, forward = negative.","s":"Nav 14","ch":"Mass and Balance","sec":"Definitions","h":"chapters/nav-14.html#n-definitions"},{"t":"Day","d":"thermals deepen the friction layer and bring stronger upper wind down → surface wind stronger, gustier and veered towards the gradient wind (NH).","s":"Met 6","ch":"Winds","sec":"Diurnal variation of surface wind (p.53–54)","h":"chapters/met-06.html#n-diurnal-variation-of-surface-wind-p-53-54"},{"t":"Delay","d":"30 minutes beyond EOBT (controlled flight) or 1 hour (uncontrolled) → amend the plan or file a new one and cancel the old.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Submission","h":"chapters/nav-16.html#n-submission"},{"t":"Density","d":"mass per unit volume (kg/m³). Pressure: force per unit area (N/m²).","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Physical terms (2-3)","h":"chapters/hb-01.html#n-physical-terms-2-3"},{"t":"Density altitude","d":"the altitude in ISA at which the prevailing density occurs.","s":"Met 4","ch":"Air Density","sec":"Definition and density altitude (p.37)","h":"chapters/met-04.html#n-definition-and-density-altitude-p-37"},{"t":"Density altitude","d":"PA corrected for non-ISA temperature ≈ PA + 118–120 ft × ISA deviation (e.g. PA 10 000, +12 °C → ≈ 12 000 ft; PA 0, 10 °C → −593 ft). DA is the PA at which the prevailing density occurs in ISA.","s":"Nav 10","ch":"DR Elements: Pressure and Altimetry","sec":"Altimeter settings and altitudes","h":"chapters/nav-10.html#n-altimeter-settings-and-altitudes"},{"t":"Depression / cyclone","d":"intense low with 2 or more closed isobars at 2 hPa interval and strong winds.","s":"Met 30","ch":"Appendices: Scales, Terms and Monsoon Drivers","sec":"A. Synoptic systems","h":"chapters/met-30.html#n-a-synoptic-systems"},{"t":"Descent","d":"work out the descent path → time and distance.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Principles of fuel planning (p.278)","h":"chapters/nav-16.html#n-principles-of-fuel-planning-p-278"},{"t":"Destination alternate","d":"if it becomes impossible or inadvisable to land at the intended destination.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Definitions (Annex 2 / Doc 4444)","h":"chapters/nav-16.html#n-definitions-annex-2-doc-4444"},{"t":"Detector unit (flux valve)","d":"three flux valves at 120°, pendulously mounted to stay horizontal, fixed in azimuth, mounted at a wing tip or fin top away from aircraft magnetism. It senses (not seeks) the magnetic meridian → works to higher latitudes.","s":"Nav 8","ch":"Magnetism and Compasses","sec":"Remote indicating (gyro-magnetic / slaved) compass","h":"chapters/nav-08.html#n-remote-indicating-gyro-magnetic-slaved-compass"},{"t":"Deviation","d":"angle between magnetic and compass north caused by metal, magnets and electrics in the aircraft. Compass north east of magnetic = easterly (+), west = westerly (−).","s":"Nav 6","ch":"Compass and Directions","sec":"Variation and deviation","h":"chapters/nav-06.html#n-variation-and-deviation"},{"t":"Dew point (DP)","d":"temperature to which air must be cooled at constant pressure to saturate it (with respect to water). Cooling below DP → condensation.","s":"Met 5","ch":"Humidity","sec":"Wet bulb, dew point, frost point (p.42)","h":"chapters/met-05.html#n-wet-bulb-dew-point-frost-point-p-42"},{"t":"Dihedral","d":"upward angle of the wing (book measures it along the quarter-chord line) relative to the lateral axis. Sweepback: angle between the quarter-chord line and a line perpendicular to the root chord (the lateral axis).","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Definitions (2-9)","h":"chapters/hb-01.html#n-definitions-2-9"},{"t":"Dip (inclination)","d":"angle of a freely suspended magnet below the horizontal. 0° at the magnetic equator, 90° at the magnetic poles. H is greatest at the magnetic equator and zero at the poles → compasses useless near the poles; a direct-reading compass is unreliable beyond ~70° N/S.","s":"Nav 8","ch":"Magnetism and Compasses","sec":"Earth's magnetism","h":"chapters/nav-08.html#n-earth-s-magnetism"},{"t":"Direction","d":"where the wind blows from (a southerly blows S → N). Given on 16 compass points or in degrees (10° steps), measured from True North (in met reports).","s":"Met 6","ch":"Winds","sec":"Basics (p.45)","h":"chapters/met-06.html#n-basics-p-45"},{"t":"Distrails","d":"clear lanes cut through cloud by exhaust heat.","s":"Met 8","ch":"Vertical Motion and Clouds","sec":"Condensation trails (p.83–84)","h":"chapters/met-08.html#n-condensation-trails-p-83-84"},{"t":"Divergence","d":"net outflow (e.g. W wind 10 kt to the west of a station, 20 kt to the east) → subsidence. Anticyclones, ridges → fine weather, poor visibility.","s":"Met 8","ch":"Vertical Motion and Clouds","sec":"Convergence and divergence (p.76–78)","h":"chapters/met-08.html#n-convergence-and-divergence-p-76-78"},{"t":"DME","d":"arc of range around the station (slant range normally ignored). TACAN = military DME; VORTAC = VOR + TACAN co-located.","s":"Nav 13","ch":"In-flight Navigation","sec":"Fixes and position lines","h":"chapters/nav-13.html#n-fixes-and-position-lines"},{"t":"Doldrums","d":"calm belt ~5°N–5°S between the trades; low pressure, cloud and rain = ITCZ.","s":"Met 6","ch":"Winds","sec":"Named winds (p.61–62)","h":"chapters/met-06.html#n-named-winds-p-61-62"},{"t":"Downburst","d":"intense damaging downdraught > 4 km across.","s":"Met 13","ch":"Thunderstorms","sec":"Air pockets, downbursts, microbursts (p.121–123)","h":"chapters/met-13.html#n-air-pockets-downbursts-microbursts-p-121-123"},{"t":"DR","d":"navigating by computation from airspeed, heading, wind and time alone. Errors accumulate with time (INS is also a DR system).","s":"Nav 9","ch":"Dead Reckoning","sec":"Terms","h":"chapters/nav-09.html#n-terms"},{"t":"Draughts","d":"updraughts stronger and deeper (can suck up gliders); downdraughts strongest from mid-cloud down; height changes 3,000–5,000 ft; > 1 km wide.","s":"Met 13","ch":"Thunderstorms","sec":"Hazards (p.117–120)","h":"chapters/met-13.html#n-hazards-p-117-120"},{"t":"Drift","d":"angle from heading to track. Track right of heading = starboard (S); left = port (P). TR = HDG + S drift − P drift. WCA = drift applied the other way (drift 7°S ⇒ WCA 7°P).","s":"Nav 9","ch":"Dead Reckoning","sec":"Triangle of velocities","h":"chapters/nav-09.html#n-triangle-of-velocities"},{"t":"Dry air","d":"no WV at all (upper troposphere, stratosphere).","s":"Met 5","ch":"Humidity","sec":"Terms (p.41–42)","h":"chapters/met-05.html#n-terms-p-41-42"},{"t":"Dry operating mass (DOM / BOM / APS)","d":"ready for a specific operation excluding usable fuel and traffic load — includes crew and their baggage, catering and removable passenger service equipment, potable water and lavatory chemicals, food and beverages.","s":"Nav 14","ch":"Mass and Balance","sec":"Mass terms","h":"chapters/nav-14.html#n-mass-terms"},{"t":"Drytra level","d":"so cold that contrails form even at 0% RH; about 2 km above the mintra level.","s":"Met 8","ch":"Vertical Motion and Clouds","sec":"Condensation trails (p.83–84)","h":"chapters/met-08.html#n-condensation-trails-p-83-84"},{"t":"Dust devil","d":"whirl over a hot spot; up to ~2 km high, ~10 m across; short-lived (willy-willy).","s":"Met 13","ch":"Thunderstorms","sec":"Tornado, waterspout, dust devil (p.124–125)","h":"chapters/met-13.html#n-tornado-waterspout-dust-devil-p-124-125"},{"t":"Dynamic (wind) pressure","d":"extra pressure when air moves, exerted in the direction opposite to the flow.","s":"Met 2","ch":"Atmospheric Pressure","sec":"Static and dynamic pressure (p.12)","h":"chapters/met-02.html#n-static-and-dynamic-pressure-p-12"},{"t":"Dynamic pressure = ½ ρ V²","d":"the kinetic energy of moving air turned into pressure when brought to rest in a pitot tube. Double the speed → 4× the dynamic pressure.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Density and pressures (2-5)","h":"chapters/hb-01.html#n-density-and-pressures-2-5"},{"t":"EAT (expected approach time)","d":"when ATC expects an aircraft that has been delayed to leave the holding fix to complete its approach or landing.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Definitions (Annex 2 / Doc 4444)","h":"chapters/nav-16.html#n-definitions-annex-2-doc-4444"},{"t":"EET (estimated elapsed time)","d":"estimated time from one significant point to another.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Definitions (Annex 2 / Doc 4444)","h":"chapters/nav-16.html#n-definitions-annex-2-doc-4444"},{"t":"El Niño","d":"unusual warming of the eastern tropical Pacific, the warm phase of ENSO (La Niña = cool phase), every 2–7 years; weak SE trades → weak Indian monsoon (severe Indian droughts occur in El Niño years, but not every El Niño gives drought); fewer cyclones in our region. La Niña → strong trades → active monsoon. Normally trades push warm water west and cause upwelling off Ecuador/Peru/Chile.","s":"Met 19","ch":"Climatology of India","sec":"SW monsoon (Jun–Sep) (p.175–180)","h":"chapters/met-19.html#n-sw-monsoon-jun-sep-p-175-180"},{"t":"Em","d":"from the Indian Ocean (crosses the equator); south of 25°N in the monsoon; very humid, sultry, small diurnal range, good visibility except in showers.","s":"Met 14","ch":"Air Masses, Fronts and WDs","sec":"Air masses over India (p.130–131)","h":"chapters/met-14.html#n-air-masses-over-india-p-130-131"},{"t":"En-route alternate","d":"to land after an abnormal or emergency condition en route.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Definitions (Annex 2 / Doc 4444)","h":"chapters/nav-16.html#n-definitions-annex-2-doc-4444"},{"t":"EOBT (estimated off-block time)","d":"when the aircraft will start moving for departure.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Definitions (Annex 2 / Doc 4444)","h":"chapters/nav-16.html#n-definitions-annex-2-doc-4444"},{"t":"Equation of time","d":"apparent solar time − mean solar time (= sundial − clock). Mean time is ahead by about 14 min near 6 February and behind by about 16 min near 3 November; EOT = 0 four times a year (April, June, September, December).","s":"Nav 1","ch":"The Solar System","sec":"Year and day","h":"chapters/nav-01.html#n-year-and-day"},{"t":"Equations of motion","d":"v = u + at; s = ut + ½at²; v² = u² + 2as; s = ½(u + v) t.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Laws (2-4)","h":"chapters/hb-01.html#n-laws-2-4"},{"t":"ETA","d":"IFR — time over the designated navaid point from which the instrument approach will start (or over the aerodrome if no navaid); VFR — time over the aerodrome.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Definitions (Annex 2 / Doc 4444)","h":"chapters/nav-16.html#n-definitions-annex-2-doc-4444"},{"t":"Evening waves","d":"after sunset low-level stability + weaker wind → waves behind small/medium hills, until morning heating.","s":"Met 16","ch":"CAT and Mountain Waves","sec":"Variation and extent (p.152)","h":"chapters/met-16.html#n-variation-and-extent-p-152"},{"t":"Exhaust trails","d":"moisture from engine exhaust condensing, at about 9 km and above; long, persistent, reveal position and track.","s":"Met 8","ch":"Vertical Motion and Clouds","sec":"Condensation trails (p.83–84)","h":"chapters/met-08.html#n-condensation-trails-p-83-84"},{"t":"Feet per hPa","d":"27 ft at MSL, 34 ft at 10 000 ft, 50 ft at 18 000 ft, 100 ft at 40 000 ft (book: 30 ft used in many sums).","s":"Nav 10","ch":"DR Elements: Pressure and Altimetry","sec":"ISA and density","h":"chapters/nav-10.html#n-isa-and-density"},{"t":"Ferrel cell (30–60°)","d":"surface air from 30° flows poleward, turned east → surface westerlies; rises near 60° (clouds, rain) = polar front region; some returns equatorward aloft.","s":"Met 20","ch":"General Circulation","sec":"Three-cell model (p.188–190)","h":"chapters/met-20.html#n-three-cell-model-p-188-190"},{"t":"Fibratus","d":"filaments without hooks. Lenticularis: lens-shaped CC/AC/SC (orographic, or lee of CB/TCU).","s":"Met 8","ch":"Vertical Motion and Clouds","sec":"Species (p.83)","h":"chapters/met-08.html#n-species-p-83"},{"t":"Filed flight plan","d":"as filed by the pilot or representative, without subsequent changes.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Definitions (Annex 2 / Doc 4444)","h":"chapters/nav-16.html#n-definitions-annex-2-doc-4444"},{"t":"Find latitude from departure","d":"cos lat = departure / d.long′ (250 NM over 4°50′ → cos lat 0.86 → 30°41′).","s":"Nav 7","ch":"Distances on the Earth","sec":"Departure (rhumb-line distance along a parallel)","h":"chapters/nav-07.html#n-departure-rhumb-line-distance-along-a-parallel"},{"t":"Fix","d":"accurate position from visual, radio or radar means. DR circle of error ≈ 5% of TAS-ish per the book's rule of thumb; Doppler DR error ellipse ≈ 0.1% along / 0.2% across distance since the fix.","s":"Nav 9","ch":"Dead Reckoning","sec":"Terms","h":"chapters/nav-09.html#n-terms"},{"t":"Fix","d":"aircraft's exact position at a time, from visual, radio or radar observations (simultaneous or transferred to a common time).","s":"Nav 13","ch":"In-flight Navigation","sec":"Fixes and position lines","h":"chapters/nav-13.html#n-fixes-and-position-lines"},{"t":"Flat plate","d":"CP moves back as AoA increases (nose-down, stable).","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Centre of pressure and aerodynamic centre (2-10)","h":"chapters/hb-01.html#n-centre-of-pressure-and-aerodynamic-centre-2-10"},{"t":"Flight levels","d":"surfaces of constant pressure referenced to 1013.25 hPa, separated by 500 ft intervals (FL50 = 5,000 ft; FL300 = 30,000 ft).","s":"Met 2","ch":"Atmospheric Pressure","sec":"Altimetry definitions (p.17)","h":"chapters/met-02.html#n-altimetry-definitions-p-17"},{"t":"Flight plan","d":"specified information given to ATS units about an intended flight or part of a flight.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Definitions (Annex 2 / Doc 4444)","h":"chapters/nav-16.html#n-definitions-annex-2-doc-4444"},{"t":"Fluid pressure at rest","d":"acts equally in all directions; acts at right angles to any surface it touches; increases with depth.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Laws (2-4)","h":"chapters/hb-01.html#n-laws-2-4"},{"t":"Flying","d":"smooth in layer cloud, turbulent in embedded CU/CB; visibility exceptionally good except in rain; gaps between layers usually give a cloud-free level except near depressions.","s":"Met 19","ch":"Climatology of India","sec":"SW monsoon (Jun–Sep) (p.175–180)","h":"chapters/met-19.html#n-sw-monsoon-jun-sep-p-175-180"},{"t":"Föhn","d":"moist air forced over a range; cools at SALR while cloud forms and rain falls on the windward side; descends dry on the lee and warms at DALR → warm, dry lee wind (Alps); 10°C or more warmer. Chinook (Rockies). Needs (a) a substantial mountain range, (b) wind blowing within 30° of the range's perpendicular (book: \"within 30° of the range\"), (c) high moisture content. Dry air may not give a Föhn.","s":"Met 6","ch":"Winds","sec":"Local winds (p.55–58)","h":"chapters/met-06.html#n-local-winds-p-55-58"},{"t":"Formation needs","d":"(a) warm sea > 26°C to ~60 m depth; (b) high RH up to ~7000 m; (c) instability and enough Coriolis; (d) very little vertical wind shear (< 20 kt between 850 and 200 hPa).","s":"Met 18","ch":"Tropical Systems","sec":"Tropical cyclones (TC / TRS) (p.159–162)","h":"chapters/met-18.html#n-tropical-cyclones-tc-trs-p-159-162"},{"t":"Forward CG","d":"more stable, heavier elevator, larger tail download → more induced drag, higher stall speed, more fuel, less range/endurance, slow pitch response.","s":"Nav 14","ch":"Mass and Balance","sec":"CG position effects","h":"chapters/nav-14.html#n-cg-position-effects"},{"t":"Fractus","d":"ragged ST/CU. Congestus: CU with strong sprouting, cauliflower (TCU).","s":"Met 8","ch":"Vertical Motion and Clouds","sec":"Species (p.83)","h":"chapters/met-08.html#n-species-p-83"},{"t":"Friction","d":"static (limiting) friction acts before movement starts; sliding (kinetic) friction is less than static.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Laws (2-4)","h":"chapters/hb-01.html#n-laws-2-4"},{"t":"Frictional eddies","d":"horizontal, vertical or slant; grow in unstable air up to ~1 km.","s":"Met 8","ch":"Vertical Motion and Clouds","sec":"Vertical motion (p.75–76)","h":"chapters/met-08.html#n-vertical-motion-p-75-76"},{"t":"Front","d":"narrow transition zone between two air masses of contrasting density (temperature/humidity); change of temperature, wind, cloud and precipitation across it.","s":"Met 14","ch":"Air Masses, Fronts and WDs","sec":"Fronts (p.131–132)","h":"chapters/met-14.html#n-fronts-p-131-132"},{"t":"Frontal fog","d":"in the continuous rain ahead of a (warm) front, saturating the surface air; or cloud lowering to the surface as the front passes.","s":"Met 7","ch":"Visibility and Fog","sec":"Other fogs (p.72)","h":"chapters/met-07.html#n-other-fogs-p-72"},{"t":"Frontal surface","d":"the sloping boundary; front = where it meets the ground.","s":"Met 14","ch":"Air Masses, Fronts and WDs","sec":"Fronts (p.131–132)","h":"chapters/met-14.html#n-fronts-p-131-132"},{"t":"Frontal TS","d":"mainly at cold fronts (occasionally warm fronts); more violent than air-mass TS; any time of day or night. A line ahead of a cold front = squall line.","s":"Met 13","ch":"Thunderstorms","sec":"Types (p.112–113)","h":"chapters/met-13.html#n-types-p-112-113"},{"t":"Frontogenesis","d":"formation/strengthening; frontolysis = weakening/dissipation. Weather only with significant density contrast.","s":"Met 14","ch":"Air Masses, Fronts and WDs","sec":"Fronts (p.131–132)","h":"chapters/met-14.html#n-fronts-p-131-132"},{"t":"Fronts","d":"warm front = gradual ascent over a large area; cold front = abrupt sharp ascent → convection, TS, squalls.","s":"Met 8","ch":"Vertical Motion and Clouds","sec":"Vertical motion (p.75–76)","h":"chapters/met-08.html#n-vertical-motion-p-75-76"},{"t":"Frost point","d":"saturation with respect to ice; cooling below it → hoar frost.","s":"Met 5","ch":"Humidity","sec":"Wet bulb, dew point, frost point (p.42)","h":"chapters/met-05.html#n-wet-bulb-dew-point-frost-point-p-42"},{"t":"Fujita scale (tornado winds)","d":"F0 35–62 kt light · F1 63–95 moderate (cars pushed off roads) · F2 96–135 considerable (roofs off, trees uprooted) · F3 136–180 severe (heavy cars thrown) · F4 181–225 devastating (houses levelled) · F5 226–275 incredible.","s":"Met 30","ch":"Appendices: Scales, Terms and Monsoon Drivers","sec":"B. Meteorological scales","h":"chapters/met-30.html#n-b-meteorological-scales"},{"t":"Gale","d":"persistent mean wind ≥ 34 kt, with depressions and cyclonic storms. A parked aircraft can survive a gale but not necessarily a sudden 60 kt squall.","s":"Met 6","ch":"Winds","sec":"Gust, lull, squall, gale (p.46–47)","h":"chapters/met-06.html#n-gust-lull-squall-gale-p-46-47"},{"t":"Gas laws","d":"Boyle — constant temperature: P ∝ 1/V (PV = constant). Charles — constant pressure: V ∝ T (volume changes by 1/273 of its 0 °C value per °C). Gay-Lussac — constant volume: P ∝ T. Avogadro — more gas, more volume (V/n = constant). Combined: PV = nRT.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Laws (2-4)","h":"chapters/hb-01.html#n-laws-2-4"},{"t":"Geocentric latitude","d":"angle at the earth's centre. Geodetic (geographic) latitude: angle between the normal to the spheroid and the equatorial plane — used on charts. Maximum difference ~11.6′ at about 45° N/S.","s":"Nav 2","ch":"The Earth","sec":"Latitude","h":"chapters/nav-02.html#n-latitude"},{"t":"Geostationary","d":"~36 000 km above the equator, period = earth's rotation, stays over one spot; 5 cover the globe; round-the-clock (e.g. METEOSAT, INSAT). Imagery interval 30 min, but generally 3-hourly pictures supplied.","s":"Met 22","ch":"Weather Radar and Met Satellites","sec":"Met satellites (p.210–213)","h":"chapters/met-22.html#n-met-satellites-p-210-213"},{"t":"Glide","d":"range set by L/D; best glide speed at max L/D; weight changes only the glide time (and best-glide speed), not the ratio; wind changes ground distance.","s":"Nav 15","ch":"Performance","sec":"Cruise, ceiling, descent, glide","h":"chapters/nav-15.html#n-cruise-ceiling-descent-glide"},{"t":"Glory","d":"coloured rings around your own shadow (often the aircraft's shadow) on cloud/fog of small droplets; diffraction (arranged like a corona).","s":"Met 10","ch":"Optical Phenomena","sec":"Other phenomena (p.97–98)","h":"chapters/met-10.html#n-other-phenomena-p-97-98"},{"t":"GMT / UTC","d":"LMT of the Greenwich meridian; UTC is kept by atomic clocks (≈ GMT); the same everywhere. GD/UD = Greenwich/universal date.","s":"Nav 5","ch":"Time","sec":"Basics","h":"chapters/nav-05.html#n-basics"},{"t":"Gradient wind","d":"parallel to curved isobars; balance of PGF, Coriolis and centripetal; better than geostrophic in mid-latitudes (friction ignored).","s":"Met 6","ch":"Winds","sec":"Cyclostrophic, gradient, isallobaric, inertial winds (p.50–51)","h":"chapters/met-06.html#n-cyclostrophic-gradient-isallobaric-inertial-winds-p-50-51"},{"t":"Graticule","d":"network of meridians and parallels on a map/chart (they are imaginary lines, not marked on the earth).","s":"Nav 2","ch":"The Earth","sec":"Longitude and meridians","h":"chapters/nav-02.html#n-longitude-and-meridians"},{"t":"Great circle (GC)","d":"circle whose plane passes through the earth's centre, dividing it into two equal halves; radius, centre and diameter = the earth's. The shorter arc of a GC is the shortest distance between two points. Only one GC through two points unless they are diametrically opposite (then infinitely many). Radio waves follow GC paths.","s":"Nav 2","ch":"The Earth","sec":"Great circle, small circle, rhumb line","h":"chapters/nav-02.html#n-great-circle-small-circle-rhumb-line"},{"t":"Green","d":"light precipitation, little/no turbulence, reduced visibility.","s":"Met 22","ch":"Weather Radar and Met Satellites","sec":"Airborne weather radar (p.209)","h":"chapters/met-22.html#n-airborne-weather-radar-p-209"},{"t":"Greenhouse gases","d":"WV, CO₂, O₃, methane — transparent to solar (short-wave) radiation but partly absorb terrestrial (long-wave) radiation and re-radiate it → keep the earth warmer. Excess → global warming.","s":"Met 1","ch":"Atmosphere","sec":"Variable gases and greenhouse gases (p.2)","h":"chapters/met-01.html#n-variable-gases-and-greenhouse-gases-p-2"},{"t":"Gross performance","d":"average fleet performance when well maintained and flown to the book. Net performance = gross reduced for contingencies (technique, below-average aircraft); it is improbable that net performance won't be achieved. Gross height used for PA in obstacle calculations and flap-retraction height; net height/flight path must clear obstacles by the statutory margin.","s":"Nav 15","ch":"Performance","sec":"Terms","h":"chapters/nav-15.html#n-terms"},{"t":"Ground discharge (thunderbolt)","d":"cloud to ground, branching (streak/ribbon lightning). Ball lightning: luminous ball 10–20 cm, moves slowly, ends with an explosion.","s":"Met 10","ch":"Optical Phenomena","sec":"Atmospheric electricity and lightning (p.99–100)","h":"chapters/met-10.html#n-atmospheric-electricity-and-lightning-p-99-100"},{"t":"GS","d":"TAS ± wind component. ETE = distance ÷ GS. ETA (IFR: over the IAF/nav aid; VFR: over the aerodrome).","s":"Nav 9","ch":"Dead Reckoning","sec":"Terms","h":"chapters/nav-09.html#n-terms"},{"t":"Gust","d":"rapid, irregular, transient increase lasting seconds (friction turbulence, uneven heating, hot afternoons). Negative fluctuation = lull.","s":"Met 6","ch":"Winds","sec":"Gust, lull, squall, gale (p.46–47)","h":"chapters/met-06.html#n-gust-lull-squall-gale-p-46-47"},{"t":"Gusts","d":"worst near the up/downdraught boundary; abrupt attitude changes.","s":"Met 13","ch":"Thunderstorms","sec":"Hazards (p.117–120)","h":"chapters/met-13.html#n-hazards-p-117-120"},{"t":"h (cloud base)","d":"0 = 0–49 m, 1 = 50–99, 2 = 100–199, 3 = 200–299, 4 = 300–599, 5 = 600–999, 6 = 1000–1499, 7 = 1500–1999, 8 = 2000–2500, 9 = no cloud below 2500.","s":"Met 24","ch":"Station Models","sec":"Codes","h":"chapters/met-24.html#n-codes"},{"t":"H → L → H","d":"High to Low, look out below = over-read. Warm to cold = over-read.","s":"Met 2","ch":"Atmospheric Pressure","sec":"Over-reading and under-reading (p.19–20)","h":"chapters/met-02.html#n-over-reading-and-under-reading-p-19-20"},{"t":"Haboob","d":"sand-raising wind, Sudan. Harmattan: hot dusty NE wind (book: central Asia). Khamsin: hot dry sandy southerly over Egypt, Apr–Jun.","s":"Met 6","ch":"Winds","sec":"Named winds (p.61–62)","h":"chapters/met-06.html#n-named-winds-p-61-62"},{"t":"Hadley cell (0–30°)","d":"strong equatorial heating → rising air, convective cloud, heavy rain = ITCZ (NE and SE trades converge; follows the sun). Air rises to the tropopause, flows poleward, is turned east by Coriolis → zonal westerlies by ~30°, strengthening with height (angular momentum + S–N temperature gradient) → subtropical jet just below the tropopause. Air piles up and subsides at ~30° → subtropical high belt; subsidence suppress…","s":"Met 20","ch":"General Circulation","sec":"Three-cell model (p.188–190)","h":"chapters/met-20.html#n-three-cell-model-p-188-190"},{"t":"Hail","d":"starts as an ice crystal, grows by collision with supercooled drops while tossed up and down; onion layers of clear (near freezing level) and rime ice. Worst from the freezing level to ~25,000 ft; damaging hail up to 45,000 ft and under the anvil (even in clear air). Max ~5.5 in; 4.5 kg (China), 3.4 kg (India) recorded. Large hail dents airframes, breaks windscreens, rips de-icer boots.","s":"Met 13","ch":"Thunderstorms","sec":"Hazards (p.117–120)","h":"chapters/met-13.html#n-hazards-p-117-120"},{"t":"Hazards","d":"poor visibility (fog, mist, haze, smoke, inversion) — worst after a WD over NW India, UP, Bihar, central India, N Bengal, Assam (S bank of the Brahmaputra); can persist days at polluted airfields like Palam (Delhi) with only 1000–2000 m at noon. Advection fog on coasts lifts by 1000–1100 IST. CAT near the STJ (NE India); mountain waves over N and E India. Freezing level lower → icing at lower levels.","s":"Met 19","ch":"Climatology of India","sec":"Winter (Jan–Feb) (p.171–173)","h":"chapters/met-19.html#n-winter-jan-feb-p-171-173"},{"t":"Hazards","d":"very low cloud (150–200 m) and strong winds in strong monsoon and depressions; visibility good except in rain (dust haze in breaks, monsoon haze on the west coast); CAT near the TEJ; long-lived TS at onset, in breaks and revivals.","s":"Met 19","ch":"Climatology of India","sec":"SW monsoon (Jun–Sep) (p.175–180)","h":"chapters/met-19.html#n-sw-monsoon-jun-sep-p-175-180"},{"t":"Hazards","d":"visibility deteriorating near industry at dawn/dusk, fog after WDs; low cloud, gales, heavy rain and TS with cyclones in the south; CAT (STJ) in the north.","s":"Met 19","ch":"Climatology of India","sec":"Post-monsoon / NE monsoon (Oct–Dec) (p.180–182)","h":"chapters/met-19.html#n-post-monsoon-ne-monsoon-oct-dec-p-180-182"},{"t":"Hazards — most hazardous flying season","d":"violent TS, DS, line squalls; dust haze to 7–8 km; dust-raising winds 30–50 kt (0900–1700 h), visibility a few hundred metres.","s":"Met 19","ch":"Climatology of India","sec":"Summer / pre-monsoon (Mar–May) (p.173–175)","h":"chapters/met-19.html#n-summer-pre-monsoon-mar-may-p-173-175"},{"t":"Heading (HDG)","d":"where the nose points (°C/M/T/Grid). Course: intended direction of flight (US usage: course = required track, track = actual path).","s":"Nav 9","ch":"Dead Reckoning","sec":"Terms","h":"chapters/nav-09.html#n-terms"},{"t":"Heat","d":"sum total of the kinetic energy of all molecules; temperature = average KE. A bathtub at 60°C holds more heat than a cup of boiling water. The thermosphere is very hot but holds little heat (few, far-apart particles) → no effect on spacecraft.","s":"Met 3","ch":"Temperature","sec":"Definitions (p.28)","h":"chapters/met-03.html#n-definitions-p-28"},{"t":"Heavy showers","d":"very low visibility, hydroplaning, engine power loss from water ingestion, noise; fractostratus below 1,000 ft.","s":"Met 13","ch":"Thunderstorms","sec":"Hazards (p.117–120)","h":"chapters/met-13.html#n-hazards-p-117-120"},{"t":"High","d":"pressure higher than surroundings at the same level, ≥ 1 closed isobar.","s":"Met 30","ch":"Appendices: Scales, Terms and Monsoon Drivers","sec":"A. Synoptic systems","h":"chapters/met-30.html#n-a-synoptic-systems"},{"t":"High (H) / anticyclone","d":"highest at centre; fair weather but poor visibility (subsidence); N hemisphere winds clockwise, veer, diverge.","s":"Met 2","ch":"Atmospheric Pressure","sec":"Pressure patterns (p.21–22) (isobars at 2 hPa)","h":"chapters/met-02.html#n-pressure-patterns-p-21-22-isobars-at-2-hpa"},{"t":"High to low (pressure or temperature): look out below","d":"the altimeter over-reads.","s":"Nav 18","ch":"Altimeter","sec":"Exam traps","h":"chapters/nav-18.html#n-exam-traps"},{"t":"Humidity mixing ratio (HMR)","d":"mass of WV per mass of dry air (g/kg). Constant when air is lifted adiabatically (no WV added or removed).","s":"Met 5","ch":"Humidity","sec":"Terms (p.41–42)","h":"chapters/met-05.html#n-terms-p-41-42"},{"t":"I — Instrument","d":"inherent/manufacturing error.","s":"Nav 18","ch":"Altimeter","sec":"Errors — \"BLIP PBT\"","h":"chapters/nav-18.html#n-errors-blip-pbt"},{"t":"IAS","d":"what the ASI shows (dynamic pressure). → CAS (= RAS): IAS corrected for position/instrument error. → EAS: CAS corrected for compressibility — the true measure of dynamic pressure, so handling depends on EAS. → TAS: EAS corrected for density: TAS = EAS ÷ √(ρ/ρ₀).","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Airspeeds (2-5)","h":"chapters/hb-01.html#n-airspeeds-2-5"},{"t":"Icing","d":"possible 0 to −30°C; clear ice worst in the first 10,000 ft above the freezing level (large supercooled drops); rime higher up; turbine flame-out, carburettor icing.","s":"Met 13","ch":"Thunderstorms","sec":"Hazards (p.117–120)","h":"chapters/met-13.html#n-hazards-p-117-120"},{"t":"IFR → VFR","d":"notify ATS specifically that the IFR flight is cancelled. Accepted only on a pilot message containing \"CANCELLING MY IFR FLIGHT\" plus any changes. ATS must never invite a change to VFR, directly or by inference.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Changing flight rules","h":"chapters/nav-16.html#n-changing-flight-rules"},{"t":"IMD","d":"India's national met service (mausam.imd.gov.in); 6 Regional Met Offices: Delhi, Mumbai, Kolkata, Chennai, Guwahati, Nagpur.","s":"Met 21","ch":"Met Services for Aviation","sec":"Purpose and organisations (p.194–195)","h":"chapters/met-21.html#n-purpose-and-organisations-p-194-195"},{"t":"Impact icing","d":"supercooled drops hit the air intake → restricts airflow → power loss.","s":"Met 12","ch":"Ice Accretion","sec":"Engine icing (p.109)","h":"chapters/met-12.html#n-engine-icing-p-109"},{"t":"In flight","d":"to the ATS unit in charge of the FIR / control area / advisory area or route (or its aeronautical telecommunication station); otherwise via another unit for retransmission. The ATS authority may limit in-flight filing in busy airspace.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Submission","h":"chapters/nav-16.html#n-submission"},{"t":"India","d":"a winter hazard, typically after a Western Disturbance (rain, then clear skies). Almost daily in winter in the Brahmaputra valley (moisture + katabatic flow). Most susceptible: NW India, UP, Bihar, Jharkhand, Chhattisgarh, Bengal, Assam (southern banks of the Brahmaputra).","s":"Met 7","ch":"Visibility and Fog","sec":"Radiation fog (p.70–71)","h":"chapters/met-07.html#n-radiation-fog-p-70-71"},{"t":"India","d":"highest frequency Oct–May over N, central and NE India (STJ); over S India in July–August (TEJ). Mostly weak–moderate; severe Dec–Feb (STJ peak). Patchy: ~120 km N–S × 250 km E–W, ~2,000 ft deep (can be deeper).","s":"Met 16","ch":"CAT and Mountain Waves","sec":"Clear Air Turbulence (p.147–148)","h":"chapters/met-16.html#n-clear-air-turbulence-p-147-148"},{"t":"India, monsoon (Jun–Sep)","d":"easterlies above 500 hPa, strengthening with height, stronger over S India; Tropical Easterly Jet ~13°N at ~15 km.","s":"Met 6","ch":"Winds","sec":"Contours and upper winds (p.59–60)","h":"chapters/met-06.html#n-contours-and-upper-winds-p-59-60"},{"t":"Indian Ocean Dipole (IOD)","d":"SST difference between the Arabian Sea and eastern Bay of Bengal; positive / neutral / negative. Positive IOD → better rain; negative → less rain, more breaks. EQUINOO (Equatorial Indian Ocean Oscillation) arises from it; positive IOD and EQUINOO increase rain.","s":"Met 30","ch":"Appendices: Scales, Terms and Monsoon Drivers","sec":"G. Other systems influencing the SW monsoon","h":"chapters/met-30.html#n-g-other-systems-influencing-the-sw-monsoon"},{"t":"Induced low / induced cyclonic circulation","d":"develops south of a WD under its influence.","s":"Met 30","ch":"Appendices: Scales, Terms and Monsoon Drivers","sec":"A. Synoptic systems","h":"chapters/met-30.html#n-a-synoptic-systems"},{"t":"Inertia","d":"reluctance of a body to change its state of rest or motion. Depends on mass, not velocity; applies to bodies at rest and in motion; it is not the same as momentum.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Physical terms (2-3)","h":"chapters/hb-01.html#n-physical-terms-2-3"},{"t":"Inertial wind","d":"no PGF; balance of centrifugal and Coriolis; Vi = fR; anticyclonic in both hemispheres.","s":"Met 6","ch":"Winds","sec":"Cyclostrophic, gradient, isallobaric, inertial winds (p.50–51)","h":"chapters/met-06.html#n-cyclostrophic-gradient-isallobaric-inertial-winds-p-50-51"},{"t":"Inferior (lower) mirage","d":"over intensely heated road, sand, beach, water → steep lapse rate.","s":"Met 10","ch":"Optical Phenomena","sec":"Mirage (p.97)","h":"chapters/met-10.html#n-mirage-p-97"},{"t":"INSAT-2E","d":"VIS 2 km; WV and TIR 8 km; CCD 1 km.","s":"Met 22","ch":"Weather Radar and Met Satellites","sec":"Met satellites (p.210–213)","h":"chapters/met-22.html#n-met-satellites-p-210-213"},{"t":"INSAT-3D","d":"launched 25 Jul 2013 from French Guiana; gives vertical temperature and humidity profiles; resolution 1 km VIS/SWIR, 4 km MIR/TIR, 8 km WV; at 82°E. INSAT-3DR: launched 8 Sep 2016, 74°E. Together 48 passes/day, new images every 15 min; Indian land scanned hourly, Indian Ocean every 90 min, swapping areas every 3 h.","s":"Met 22","ch":"Weather Radar and Met Satellites","sec":"Met satellites (p.210–213)","h":"chapters/met-22.html#n-met-satellites-p-210-213"},{"t":"Insolation","d":"total solar radiation received over an area; depends on the obliquity of the sun's rays: max when the sun is overhead, least at sunrise/sunset; max over the tropics, least at the poles.","s":"Met 3","ch":"Temperature","sec":"Insolation and radiation laws (p.30)","h":"chapters/met-03.html#n-insolation-and-radiation-laws-p-30"},{"t":"Instrument errors","d":"pressure falls under a growing/mature CB → altimeter over-reads; pitot blocked by water → wrong ASI.","s":"Met 13","ch":"Thunderstorms","sec":"Hazards (p.117–120)","h":"chapters/met-13.html#n-hazards-p-117-120"},{"t":"Inter-Tropical Convergence Zone","d":"narrow zone where Tm/Tc air from the north meets Tm/Em air from the south (converging trades). Usually along the equatorial trough (shallow trough in the doldrums). Also called the equatorial front.","s":"Met 18","ch":"Tropical Systems","sec":"ITCZ (p.154–155)","h":"chapters/met-18.html#n-itcz-p-154-155"},{"t":"Intermediate stops","d":"initial clearance limit = first destination; new clearance for each stage. Later stages become active for ATS/SAR only when departure from the previous aerodrome is notified (scheduled flights through several control areas may be cleared through intermediate stops after ACC co-ordination).","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Submission","h":"chapters/nav-16.html#n-submission"},{"t":"Inversion (warmer aloft)","d":"climbing at constant TAS → Mach ↓ (LSS ↑), CAS ↓; at constant Mach → TAS ↑, CAS ↓; at constant CAS → TAS ↑ (Mach changes little, since LSS also rises).","s":"Nav 11","ch":"DR Elements: Temperature and Airspeed","sec":"Climbs and descents (book's graphs)","h":"chapters/nav-11.html#n-climbs-and-descents-book-s-graphs"},{"t":"Inversion fog","d":"in an anticyclone, subsiding cold air contacts a warm water body.","s":"Met 7","ch":"Visibility and Fog","sec":"Other fogs (p.72)","h":"chapters/met-07.html#n-other-fogs-p-72"},{"t":"Irisation","d":"colours/bands parallel to cloud margins (pink predominates), by diffraction.","s":"Met 10","ch":"Optical Phenomena","sec":"Other phenomena (p.97–98)","h":"chapters/met-10.html#n-other-phenomena-p-97-98"},{"t":"ISA","d":"MSL 15 °C, 1013.25 hPa (29.92 inHg, 760 mm, 14.7 lb/in²), density 1.225 kg/m³; lapse 1.98 °C/1000 ft to 36 090 ft, then −56.5 °C to ~65 600 ft. (Jet standard: 2 °C/1000 ft.)","s":"Nav 10","ch":"DR Elements: Pressure and Altimetry","sec":"ISA and density","h":"chapters/nav-10.html#n-isa-and-density"},{"t":"ISA layer (below the tropopause)","d":"climbing at constant CAS → TAS ↑ and Mach ↑; at constant Mach → TAS ↓ and CAS ↓; at constant TAS → CAS ↓, Mach ↑.","s":"Nav 11","ch":"DR Elements: Temperature and Airspeed","sec":"Climbs and descents (book's graphs)","h":"chapters/nav-11.html#n-climbs-and-descents-book-s-graphs"},{"t":"Isallobaric wind","d":"when pressure changes rapidly, an isallobaric force acts from higher to lower isallobar → deflects wind towards falling pressure.","s":"Met 6","ch":"Winds","sec":"Cyclostrophic, gradient, isallobaric, inertial winds (p.50–51)","h":"chapters/met-06.html#n-cyclostrophic-gradient-isallobaric-inertial-winds-p-50-51"},{"t":"Isallobars","d":"lines of equal pressure tendency. Greatest fall = isallobaric low; greatest rise = isallobaric high.","s":"Met 2","ch":"Atmospheric Pressure","sec":"Pressure gradient, tendency, isallobars (p.16–17)","h":"chapters/met-02.html#n-pressure-gradient-tendency-isallobars-p-16-17"},{"t":"Iso-lines","d":"isobar pressure · isohyet rainfall · isotach wind speed · isogon wind direction · isotherm temperature · isallobar pressure change · isopycnic density · isohel sunshine · isomer % of average annual rainfall in a month · isopleth any quantity (generic) · isohypse / contour height · streamline tangential to wind direction.","s":"Met 30","ch":"Appendices: Scales, Terms and Monsoon Drivers","sec":"D. Miscellaneous terms","h":"chapters/met-30.html#n-d-miscellaneous-terms"},{"t":"Isoclinals","d":"equal dip. Aclinic line: zero dip (magnetic equator). Isogonals: equal variation (converge at both the magnetic and geographic poles). Agonic line: zero variation. Variation at a place changes slowly over time (annual change shown on charts).","s":"Nav 8","ch":"Magnetism and Compasses","sec":"Earth's magnetism","h":"chapters/nav-08.html#n-earth-s-magnetism"},{"t":"Isogonals","d":"lines of equal variation. Agonic line: zero variation.","s":"Nav 6","ch":"Compass and Directions","sec":"Variation and deviation","h":"chapters/nav-06.html#n-variation-and-deviation"},{"t":"Isothermal layer","d":"LSS constant, so constant Mach = constant TAS; climbing at constant CAS → TAS ↑, Mach ↑ (CAS falls at constant TAS/Mach).","s":"Nav 11","ch":"DR Elements: Temperature and Airspeed","sec":"Climbs and descents (book's graphs)","h":"chapters/nav-11.html#n-climbs-and-descents-book-s-graphs"},{"t":"Isothermal process","d":"heat flows in/out so temperature stays constant.","s":"Met 9","ch":"Stability and Instability","sec":"Processes (p.87)","h":"chapters/met-09.html#n-processes-p-87"},{"t":"Jet stream","d":"strong, narrow current of wind along a quasi-horizontal axis in the upper troposphere; in both hemispheres all year; wavy, serpentine path.","s":"Met 15","ch":"Jet Streams","sec":"Definition (p.140)","h":"chapters/met-15.html#n-definition-p-140"},{"t":"Jet-stream cloud","d":"very long cirrus streaks.","s":"Met 22","ch":"Weather Radar and Met Satellites","sec":"Reading satellite images (p.212–213)","h":"chapters/met-22.html#n-reading-satellite-images-p-212-213"},{"t":"Kalpana-1","d":"launched 12 Sep 2002, 74°E; INSAT-3A: 10 Apr 2003, 93.5°E. Both have 3-channel VHRR: VIS (0.55–0.75 µm), IR (10.5–12.5 µm), WV (5.7–7.1 µm); resolution 2 km VIS, 8 km IR/WV; INSAT-3A also a 3-channel CCD (VIS, NIR, SWIR) at 1 km. ~48 images/day from Kalpana-1, 9 from INSAT-3A (CCD daytime, 5 times).","s":"Met 22","ch":"Weather Radar and Met Satellites","sec":"Met satellites (p.210–213)","h":"chapters/met-22.html#n-met-satellites-p-210-213"},{"t":"Kata (stable) warm front","d":"CI, CS ~1000 km ahead → AS, NS 400–500 km ahead → steady, increasing, prolonged precipitation → just ahead: drizzle, low ST, frontal fog; freezing rain/fog (FZRA/FZFG) ahead in cold air. After passage: fog clears, partly clear, warmer and humid.","s":"Met 14","ch":"Air Masses, Fronts and WDs","sec":"Warm front (p.133–134)","h":"chapters/met-14.html#n-warm-front-p-133-134"},{"t":"Kata cold front","d":"slope ~1:120, ~20 kt; warm air sinks aloft → limited vertical growth; ST, NS, AS + CU/CB; widespread rain; showers ahead and just behind; fast ones can produce a line squall 100–300 km ahead.","s":"Met 14","ch":"Air Masses, Fronts and WDs","sec":"Cold front (p.132–133)","h":"chapters/met-14.html#n-cold-front-p-132-133"},{"t":"Katabatic","d":"night downslope cold wind (slope cools by radiation); few knots but pools cold air in hollows → frost, mist, fog. Common in NE India (morning fog/TS). Over snow-covered slopes can blow by day too. Bora (Adriatic, gusts > 100 kt), Greenland, Black Sea.","s":"Met 6","ch":"Winds","sec":"Local winds (p.55–58)","h":"chapters/met-06.html#n-local-winds-p-55-58"},{"t":"Kepler's laws","d":"(i) planets move in ellipses with the sun at a focus; (ii) the line joining planet and sun sweeps equal areas in equal times → orbital speed is fastest when closest (perihelion), slowest when farthest (aphelion).","s":"Nav 1","ch":"The Solar System","sec":"The earth's orbit","h":"chapters/nav-01.html#n-the-earth-s-orbit"},{"t":"Kilometre","d":"originally 1/10 000 of the meridian from equator to pole. 1 km = 3280 ft = 0.54 NM; 1 NM = 1.852 km; 1 m = 3.28 ft.","s":"Nav 7","ch":"Distances on the Earth","sec":"Units","h":"chapters/nav-07.html#n-units"},{"t":"Kinematic viscosity (ν = μ/ρ)","d":"1.46 × 10⁻⁵ m²/s at ISA MSL; density falls faster than μ, so ν rises with height, even in the stratosphere.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Viscosity and Reynolds number (2-8)","h":"chapters/hb-01.html#n-viscosity-and-reynolds-number-2-8"},{"t":"L — Lag","d":"from hysteresis and mechanical friction; virtually removed in the servo altimeter by the electromechanical pick-off.","s":"Nav 18","ch":"Altimeter","sec":"Errors — \"BLIP PBT\"","h":"chapters/nav-18.html#n-errors-blip-pbt"},{"t":"L → H → L","d":"Low to High = under-read; cold to warm = under-read.","s":"Met 2","ch":"Atmospheric Pressure","sec":"Over-reading and under-reading (p.19–20)","h":"chapters/met-02.html#n-over-reading-and-under-reading-p-19-20"},{"t":"Lambert","d":"chart convergence = d.long × sin (parallel of origin). Polar stereographic: = d.long.","s":"Nav 4","ch":"Convergency","sec":"On charts","h":"chapters/nav-04.html#n-on-charts"},{"t":"Lapse rate","d":"decrease of temperature with height (positive when temperature falls). Troposphere average 6.5°C/km.","s":"Met 9","ch":"Stability and Instability","sec":"Processes (p.87)","h":"chapters/met-09.html#n-processes-p-87"},{"t":"Large-scale","d":"pressure systems, fronts, upper troughs/ridges, mountains → hundreds of km; mountain waves may reach the upper stratosphere.","s":"Met 8","ch":"Vertical Motion and Clouds","sec":"Vertical motion (p.75–76)","h":"chapters/met-08.html#n-vertical-motion-p-75-76"},{"t":"Latent heat","d":"heat absorbed or released in a change of phase; absorbed solid→liquid→gas, released in the reverse. Turning boiling water into vapour needs > 5× the heat needed to bring ice-cold water to the boil. Released again on condensation.","s":"Met 3","ch":"Temperature","sec":"Definitions (p.28)","h":"chapters/met-03.html#n-definitions-p-28"},{"t":"Latent instability","d":"initially stable air becomes unstable after forced ascent. Real latent: energy needed to lift it ≪ energy released later. Pseudo latent: lifting energy > energy released.","s":"Met 9","ch":"Stability and Instability","sec":"Stability criteria (p.89)","h":"chapters/met-09.html#n-stability-criteria-p-89"},{"t":"Latitude","d":"angle along the meridian from the equator (datum) to the place, 0–90° N or S.","s":"Nav 2","ch":"The Earth","sec":"Latitude","h":"chapters/nav-02.html#n-latitude"},{"t":"LCC","d":"mathematically made conformal using two standard parallels. Scale correct on the standard parallels, contracts slightly between them (minimum at the parallel of origin, error < 1%), expands outside. The nominal scale is that at the standard parallels.","s":"Nav 3","ch":"Projections","sec":"Simple conic and Lambert's conformal conic (LCC)","h":"chapters/nav-03.html#n-simple-conic-and-lambert-s-conformal-conic-lcc"},{"t":"Level","d":"keep watching the temp deviation and FL.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Principles of fuel planning (p.278)","h":"chapters/nav-16.html#n-principles-of-fuel-planning-p-278"},{"t":"Lift","d":"aerodynamic force at 90° to the relative airflow (flight path). Total reaction (TR): resultant of all aerodynamic forces on the wing, acting through the centre of pressure; it resolves into lift and drag.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Definitions (2-9)","h":"chapters/hb-01.html#n-definitions-2-9"},{"t":"Light","d":"faint thunder, lightning at long intervals.","s":"Met 13","ch":"Thunderstorms","sec":"Intensity (p.117)","h":"chapters/met-13.html#n-intensity-p-117"},{"t":"Light aircraft / gliders / helicopters","d":"warning when wind is expected ≥ 17 kt (prefix \"Warnings for Light Aircraft\"); not sent beyond the aerodrome.","s":"Met 21","ch":"Met Services for Aviation","sec":"Warnings (p.200)","h":"chapters/met-21.html#n-warnings-p-200"},{"t":"Lightning","d":"needs ~3×10⁶ V/m in clear air (~1×10⁶ V/m in cloud); usually not catastrophic (aircraft bonding) but burns/holes, compass errors, damaged electronics, radio noise, temporary blinding. Most likely between +10°C and −10°C. Thunder = shock wave from the heated air.","s":"Met 13","ch":"Thunderstorms","sec":"Hazards (p.117–120)","h":"chapters/met-13.html#n-hazards-p-117-120"},{"t":"Liquid swirl","d":"fluid dragged round in turns carries the magnets in the direction of turn; adds to or reduces turning error; at the equator it is the only turning error.","s":"Nav 8","ch":"Magnetism and Compasses","sec":"Errors due to dip (direct-reading compass)","h":"chapters/nav-08.html#n-errors-due-to-dip-direct-reading-compass"},{"t":"LMT (Local Mean Time)","d":"time on the observer's meridian measured from the mean sun's transit of the observer's anti-meridian (midnight = 0000). Places east are ahead, west behind.","s":"Nav 5","ch":"Time","sec":"Basics","h":"chapters/nav-05.html#n-basics"},{"t":"Loading index (LI)","d":"scaled-down moment; DOI: index at the DOM. Ballast: removable or fixed mass to bring the CG into range.","s":"Nav 14","ch":"Mass and Balance","sec":"Definitions","h":"chapters/nav-14.html#n-definitions"},{"t":"Local / Area forecast","d":"3 times a day, valid 12 h: issued 0700 (valid 0730–1930), 1300 (1330–0130), 1800 (1830–0930) IST. Area = 100 NM or more; local = 50 NM. Contains surface wind, visibility, weather, cloud, upper winds/temps, sunrise/sunset, warnings.","s":"Met 21","ch":"Met Services for Aviation","sec":"Aviation forecasts (p.197–199)","h":"chapters/met-21.html#n-aviation-forecasts-p-197-199"},{"t":"Longitude","d":"angle at the centre along the equator from the prime (Greenwich) meridian (datum) to the meridian of the place, 0–180° E or W.","s":"Nav 2","ch":"The Earth","sec":"Longitude and meridians","h":"chapters/nav-02.html#n-longitude-and-meridians"},{"t":"Lost procedure","d":"climb (range of radios/radar), use VOR/ADF/GPS, contact ATC (DF, radar), emergency 121.5 MHz, squawk 7700.","s":"Nav 9","ch":"Dead Reckoning","sec":"Time and DR position","h":"chapters/nav-09.html#n-time-and-dr-position"},{"t":"Low (L)","d":"closed isobar(s), lowest at centre. 2+ closed isobars = depression; stronger = cyclone / severe cyclone. N hemisphere winds anticlockwise and converging → upward motion → bad weather, but visibility better than in a high. Winds back. Surface wind < 17 kt (for a \"low\").","s":"Met 2","ch":"Atmospheric Pressure","sec":"Pressure patterns (p.21–22) (isobars at 2 hPa)","h":"chapters/met-02.html#n-pressure-patterns-p-21-22-isobars-at-2-hpa"},{"t":"Low-level / VFR flights","d":"up to FL100 (FL150 or above in mountains); poor visibility (≤ 5000 m), phenomena likely to lower widespread visibility below 5000 m, cloud affecting flight, SIGMET.","s":"Met 28","ch":"Met Documentation and Briefing","sec":"Briefing (p.260–261)","h":"chapters/met-28.html#n-briefing-p-260-261"},{"t":"Low-level jet (LLJ)","d":"strong winds at 1–3 km in the SW monsoon over the Peninsula; continuation of the Somali jet off East Africa; enhances monsoon rain.","s":"Met 15","ch":"Jet Streams","sec":"Tropical Easterly Jet (p.143)","h":"chapters/met-15.html#n-tropical-easterly-jet-p-143"},{"t":"Low-level WS","d":"along final approach, runway, take-off and initial climb. Vertical WS: change of horizontal wind with height. Horizontal WS: with distance. Up/downdraughts: change of the vertical component with distance.","s":"Met 6","ch":"Winds","sec":"Wind shear (p.54–55)","h":"chapters/met-06.html#n-wind-shear-p-54-55"},{"t":"MAC (mean aerodynamic chord)","d":"chord of an equivalent rectangular wing; CG often given as % MAC (LeMAC/TeMAC give its position). For longitudinal stability the CG must be ahead of the centre of lift.","s":"Nav 14","ch":"Mass and Balance","sec":"Definitions","h":"chapters/nav-14.html#n-definitions"},{"t":"Madden–Julian Oscillation (MJO)","d":"eastward-moving (W → E) equatorial wave of cloud, rain, wind and pressure, 30–60-day cycle (Madden & Julian, 1971); over the Indian Ocean in the monsoon → good rain; shorter (~30-day) cycle → better monsoon (2–3 good spells); ≥ 40 days reduces rain.","s":"Met 30","ch":"Appendices: Scales, Terms and Monsoon Drivers","sec":"G. Other systems influencing the SW monsoon","h":"chapters/met-30.html#n-g-other-systems-influencing-the-sw-monsoon"},{"t":"Magnetic direction (°M)","d":"measured from magnetic north — where a freely suspended magnet points (the magnetic and geographic axes are not aligned).","s":"Nav 6","ch":"Compass and Directions","sec":"Three norths","h":"chapters/nav-06.html#n-three-norths"},{"t":"Map","d":"graticule plus lots of ground detail. Chart: graticule with little detail, made for a purpose (navigation).","s":"Nav 3","ch":"Projections","sec":"Why projections distort","h":"chapters/nav-03.html#n-why-projections-distort"},{"t":"Mascarene High","d":"semi-permanent high in the S Indian Ocean (~4000 km from India), develops from mid-April; drives cross-equatorial flow; stronger high → stronger surge, heavier W-coast rain.","s":"Met 30","ch":"Appendices: Scales, Terms and Monsoon Drivers","sec":"G. Other systems influencing the SW monsoon","h":"chapters/met-30.html#n-g-other-systems-influencing-the-sw-monsoon"},{"t":"Mass","d":"quantity of matter in a body. Weight (newtons) = mass × g: the force pulling it towards the earth's centre. M = W / g.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Physical terms (2-3)","h":"chapters/hb-01.html#n-physical-terms-2-3"},{"t":"Maxtra level","d":"in the stratosphere; above it no contrails form.","s":"Met 8","ch":"Vertical Motion and Clouds","sec":"Condensation trails (p.83–84)","h":"chapters/met-08.html#n-condensation-trails-p-83-84"},{"t":"Mean aerodynamic chord (MAC)","d":"the chord through the centroid of the wing area; a rectangular wing of that chord would have the same pitching-moment characteristics.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Definitions (2-9)","h":"chapters/hb-01.html#n-definitions-2-9"},{"t":"Mean camber line","d":"line from LE to TE midway between the upper and lower surfaces; max camber: greatest distance between it and the chord line.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Definitions (2-9)","h":"chapters/hb-01.html#n-definitions-2-9"},{"t":"Mean solar day","d":"based on the mean sun, a fictitious sun moving at constant speed along the celestial equator = 24 h.","s":"Nav 1","ch":"The Solar System","sec":"Year and day","h":"chapters/nav-01.html#n-year-and-day"},{"t":"Mercator","d":"meridians parallel → chart convergence 0; correct only at the equator. All RLs straight; GCs curve concave to the equator (on the polar side of the RL).","s":"Nav 4","ch":"Convergency","sec":"On charts","h":"chapters/nav-04.html#n-on-charts"},{"t":"Mercury barometer","d":"most accurate; pressure balanced by a mercury column.","s":"Met 2","ch":"Atmospheric Pressure","sec":"Measurement (p.15)","h":"chapters/met-02.html#n-measurement-p-15"},{"t":"Meridian","d":"semi-great circle pole to pole joining places of equal longitude; defines true north–south; crosses the equator at 90°. Anti-meridian = longitude 180° away, opposite name (030°W ↔ 150°E); meridian + anti-meridian = a full great circle.","s":"Nav 2","ch":"The Earth","sec":"Longitude and meridians","h":"chapters/nav-02.html#n-longitude-and-meridians"},{"t":"Meridians","d":"parallel, equally spaced, vertical straight lines. Parallels: straight, spacing increases away from the equator.","s":"Nav 3","ch":"Projections","sec":"Mercator (direct)","h":"chapters/nav-03.html#n-mercator-direct"},{"t":"Mesoscale Convective Complex (MCC)","d":"near-circular cluster of interacting TS over a huge area (~1000× an air-mass TS); new cells keep forming → life 6–24 h; severe weather, tornadoes, flash floods; near fronts and in the ITCZ.","s":"Met 13","ch":"Thunderstorms","sec":"Types (p.112–113)","h":"chapters/met-13.html#n-types-p-112-113"},{"t":"Mesoscale weather","d":"local phenomena such as TS, DS, land/sea breeze, katabatic wind.","s":"Met 13","ch":"Thunderstorms","sec":"Types (p.112–113)","h":"chapters/met-13.html#n-types-p-112-113"},{"t":"Met sub-divisions","d":"NW India J&K, HP, Punjab, Haryana, Delhi, E & W UP, Rajasthan, Uttarakhand · East Jharkhand, Bihar, Odisha, WB, Sikkim · NE Arunachal, Nagaland, Mizoram, Manipur, Tripura, Assam, Meghalaya · South TN, AP, Kerala, Karnataka, Lakshadweep, A&N · West Konkan & Goa, Madhya Maharashtra, Marathwada, Gujarat, Saurashtra & Kutch · Central MP, Chhattisgarh, Vidarbha.","s":"Met 30","ch":"Appendices: Scales, Terms and Monsoon Drivers","sec":"D. Miscellaneous terms","h":"chapters/met-30.html#n-d-miscellaneous-terms"},{"t":"METAR","d":"routine aerodrome report, every half hour, with a TREND appended.","s":"Met 21","ch":"Met Services for Aviation","sec":"Observations and reports","h":"chapters/met-21.html#n-observations-and-reports"},{"t":"Microburst","d":"concentrated downdraught ~4 km across, lasts 1–5 min; most hazardous; surface wind difference up to 90 kt, even opposite directions. Wet (heavy rain, evaporative cooling) or dry (high-based TS, virga evaporating under the anvil/AC).","s":"Met 6","ch":"Winds","sec":"Wind shear (p.54–55)","h":"chapters/met-06.html#n-wind-shear-p-54-55"},{"t":"Mid-tropospheric (subtropical) cyclone","d":"circulation at 500–700 hPa around 18–28°N, 60–80°E with a surface trough; heavy rain over W India / Gujarat / NE Arabian Sea (W/SW of centre); e.g. Mumbai floods 2005.","s":"Met 19","ch":"Climatology of India","sec":"SW monsoon (Jun–Sep) (p.175–180)","h":"chapters/met-19.html#n-sw-monsoon-jun-sep-p-175-180"},{"t":"Minimum Sector Altitude","d":"lowest altitude giving 300 m (1000 ft) clearance over all objects within a sector of a 46 km (25 NM) circle centred on a radio aid.","s":"Met 25","ch":"METAR, SPECI and TREND","sec":"Reporting rules","h":"chapters/met-25.html#n-reporting-rules"},{"t":"Mintra level","d":"below it no contrails form; for jets ≈ the level where temperature is about −45°C (at 100% RH).","s":"Met 8","ch":"Vertical Motion and Clouds","sec":"Condensation trails (p.83–84)","h":"chapters/met-08.html#n-condensation-trails-p-83-84"},{"t":"Moderate","d":"loud thunder, frequent lightning, moderate/heavy showers, light hail; max wind 15–40 kt.","s":"Met 13","ch":"Thunderstorms","sec":"Intensity (p.117)","h":"chapters/met-13.html#n-intensity-p-117"},{"t":"Moist air","d":"normal air; also called \"unsaturated\" or \"dry\" air at its temperature and pressure.","s":"Met 5","ch":"Humidity","sec":"Terms (p.41–42)","h":"chapters/met-05.html#n-terms-p-41-42"},{"t":"Momentum","d":"mass × velocity (kg m/s): the tendency to keep moving once moving.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Physical terms (2-3)","h":"chapters/hb-01.html#n-physical-terms-2-3"},{"t":"Momentum (deflection) theory","d":"the wing deflects a stream of air; force = rate of change of momentum = mass flow × Δv (book's worked form F ≈ 1.4 ρ A V² for its vector example). The force grows with angle of attack and camber — how a windmill works.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Streamline flow and lift theories (2-6 to 2-7)","h":"chapters/hb-01.html#n-streamline-flow-and-lift-theories-2-6-to-2-7"},{"t":"Monsoon","d":"any markedly seasonal wind (E and SE Asia).","s":"Met 6","ch":"Winds","sec":"Named winds (p.61–62)","h":"chapters/met-06.html#n-named-winds-p-61-62"},{"t":"Monsoon depressions","d":"2–3 a month from the north Bay, moving N/W, spreading rain over central and north India.","s":"Met 19","ch":"Climatology of India","sec":"SW monsoon (Jun–Sep) (p.175–180)","h":"chapters/met-19.html#n-sw-monsoon-jun-sep-p-175-180"},{"t":"Monsoon trough","d":"normal position Ganganagar–Allahabad–Kolkata–head Bay ≈ ITCZ; Bay branch north of it, Arabian Sea branch south; slopes south with height (700 hPa ≈ 22°N Gujarat–Odisha; 500 hPa ≈ 10–15°N); its N–S swings govern rainfall.","s":"Met 19","ch":"Climatology of India","sec":"SW monsoon (Jun–Sep) (p.175–180)","h":"chapters/met-19.html#n-sw-monsoon-jun-sep-p-175-180"},{"t":"Mountain (lee) wave","d":"oscillations on the lee side of high ground due to disturbance of horizontal flow; reach great heights and far downwind.","s":"Met 16","ch":"CAT and Mountain Waves","sec":"Mountain waves — definition and conditions (p.149)","h":"chapters/met-16.html#n-mountain-waves-definition-and-conditions-p-149"},{"t":"MSL","d":"average of high and low tides.","s":"Met 2","ch":"Atmospheric Pressure","sec":"Altimetry definitions (p.17)","h":"chapters/met-02.html#n-altimetry-definitions-p-17"},{"t":"Multi-cell cluster","d":"cells last ~20 min each, the cluster for hours; near mountains, cold fronts, troughs.","s":"Met 13","ch":"Thunderstorms","sec":"Classification by structure (p.113)","h":"chapters/met-13.html#n-classification-by-structure-p-113"},{"t":"Multi-cell line = squall line","d":"along/ahead of cold fronts; hundreds of km; heavy rain, hail, lightning, very strong winds, isolated tornadoes. A very powerful one = derecho. Also in outer rain bands of tropical cyclones.","s":"Met 13","ch":"Thunderstorms","sec":"Classification by structure (p.113)","h":"chapters/met-13.html#n-classification-by-structure-p-113"},{"t":"Nacreous (mother-of-pearl)","d":"upper stratosphere; like CI or AC lenticularis with strong irisation; ice or supercooled drops; seen mainly in Scotland and Scandinavia.","s":"Met 8","ch":"Vertical Motion and Clouds","sec":"The ten genera (p.79–80)","h":"chapters/met-08.html#n-the-ten-genera-p-79-80"},{"t":"Nautical mile","d":"arc subtending 1′ at the earth's centre (along a great circle/meridian). Varies slightly: ~6046 ft at the equator, ~6080 ft (standard, at 45°), ~6108–6170 ft at the poles (book quotes 6170) — longer at the poles. 1° = 60 NM; 1′ = 1 NM. Defined value 1852 m = 6076 ft.","s":"Nav 7","ch":"Distances on the Earth","sec":"Units","h":"chapters/nav-07.html#n-units"},{"t":"Neutrally stable","d":"CG at or near the aerodynamic centre (neutral point); no restoring tendency.","s":"Nav 14","ch":"Mass and Balance","sec":"CG position effects","h":"chapters/nav-14.html#n-cg-position-effects"},{"t":"Newton's laws","d":"(1) a body stays at rest or in uniform straight-line motion unless a force acts; (2) rate of change of momentum ∝ applied force, in the force's direction; (3) action and reaction are equal and opposite.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Laws (2-4)","h":"chapters/hb-01.html#n-laws-2-4"},{"t":"Night","d":"friction layer shrinks; upper wind cannot reach down → surface wind weak and backed (crosses isobars more); marked wind shear near 500 m (strong above, weak below) — a hazard.","s":"Met 6","ch":"Winds","sec":"Diurnal variation of surface wind (p.53–54)","h":"chapters/met-06.html#n-diurnal-variation-of-surface-wind-p-53-54"},{"t":"Noctilucent","d":"upper mesosphere (80–85 km); bluish/silvery; visible just after sunset/before sunrise, 45°–72°N (mostly ~55°N), late May to mid-August; ice particles.","s":"Met 8","ch":"Vertical Motion and Clouds","sec":"The ten genera (p.79–80)","h":"chapters/met-08.html#n-the-ten-genera-p-79-80"},{"t":"Nocturnal radiation","d":"radiation from the earth at night (no incoming short wave). Warmer earth → more intense nocturnal radiation.","s":"Met 3","ch":"Temperature","sec":"Solar, terrestrial and nocturnal radiation (p.31)","h":"chapters/met-03.html#n-solar-terrestrial-and-nocturnal-radiation-p-31"},{"t":"Non-scheduled flights","d":"signed and submitted by the PIC, or by an approved flight dispatcher of the operator/authorised handling agency. Those persons may take ATS, COMM and MET briefing.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"India: filing flight plans","h":"chapters/nav-16.html#n-india-filing-flight-plans"},{"t":"Non-scheduled flights into/across Indian airspace","d":"state the DGCA authority (YA No.) or AHQ authority (AOR No.) in Item 18.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"India: filing flight plans","h":"chapters/nav-16.html#n-india-filing-flight-plans"},{"t":"Normand's theorem","d":"draw DALR up from the dry bulb, SALR from the wet bulb and the isohygric from the dew point — the three meet at the Normand point. The first one from surface values = LCL (likely cloud base).","s":"Met 9","ch":"Stability and Instability","sec":"Tephigram (p.90–91)","h":"chapters/met-09.html#n-tephigram-p-90-91"},{"t":"Nowcasting","d":"< 24 h (TREND, TAF, SIGMET, local forecasts, aerodrome warnings).","s":"Met 21","ch":"Met Services for Aviation","sec":"Types of forecast by range","h":"chapters/met-21.html#n-types-of-forecast-by-range"},{"t":"Oblique","d":"cylinder tangent along a chosen great circle (route). Conformal; scale correct along that GC; within ~500 NM treat as constant scale.","s":"Nav 3","ch":"Projections","sec":"Transverse and oblique Mercator","h":"chapters/nav-03.html#n-transverse-and-oblique-mercator"},{"t":"Off ATS routes","d":"points normally ≤ 30 minutes or 370 km (200 NM) apart, plus every change point. Where required: east–west flights between 70°N and 70°S by half/whole degrees of latitude at 10° longitude intervals (20° outside those latitudes), points ideally ≤ 1 hour apart; north–south flights by whole degrees of longitude at parallels 5° apart.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Item 15 — Route","h":"chapters/nav-16.html#n-item-15-route"},{"t":"On ATS routes","d":"first ATS route designator (or DCT + joining point + route), then every point where speed/level, route or flight rules change, each followed by the next route designator (even if the same) or DCT. Point of transition between lower and upper routes in the same direction need not be inserted.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Item 15 — Route","h":"chapters/nav-16.html#n-item-15-route"},{"t":"Operating mass (OM)","d":"DOM + take-off fuel. Zero fuel mass (ZFM) = DOM + traffic load. Take-off mass (TOM) at the start of the take-off run. Ramp/taxi mass = TOM + taxi fuel.","s":"Nav 14","ch":"Mass and Balance","sec":"Mass terms","h":"chapters/nav-14.html#n-mass-terms"},{"t":"Orthomorphic / conformal","d":"bearings shown correctly. Needs (a) meridians and parallels crossing at 90° and (b) scale the same in all directions at a point.","s":"Nav 3","ch":"Projections","sec":"Orthomorphism (conformality)","h":"chapters/nav-03.html#n-orthomorphism-conformality"},{"t":"Other factors","d":"alternate, diversion and hold, circuit and landing, reserve. A diversion is assumed after an unsuccessful landing attempt, so diversion tables already include overshoot, climb to a suitable level and reserve fuel.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Principles of fuel planning (p.278)","h":"chapters/nav-16.html#n-principles-of-fuel-planning-p-278"},{"t":"Outputs","d":"pressure altitude (static pressure corrected to the ICAO Standard Atmosphere); airspeed (IAS, or TAS for DR/inertial navigation); air density (gas laws, for engine controls); Mach number (from pitot and static pressures); air temperature (corrected for frictional heating and compression at the probe); angle of attack (measured AoA corrected for airspeed = true AoA); rates of change of altitude and speed.","s":"Nav 17","ch":"Air Data Systems","sec":"Air data system","h":"chapters/nav-17.html#n-air-data-system"},{"t":"Ozone (O₃)","d":"forms in the upper atmosphere, absorbs UV and raises temperature; protects from skin cancer, sunburn, cataracts.","s":"Met 1","ch":"Atmosphere","sec":"CO₂, ozone and particles (p.3)","h":"chapters/met-01.html#n-co-ozone-and-particles-p-3"},{"t":"Ozone hole","d":"thinning, mainly over polar regions, caused by pollution and halocarbons/CFCs (refrigerants, solvents) that release halogens in the stratosphere by photodissociation.","s":"Met 1","ch":"Atmosphere","sec":"CO₂, ozone and particles (p.3)","h":"chapters/met-01.html#n-co-ozone-and-particles-p-3"},{"t":"P — Position","d":"dynamic-pressure interference at the static source, from (a) incorrect static source position, (b) induced causes (slip/skid, low speed, high or low angle of attack, standby/alternate source), (c) ground effect (wing-tip vortices and airflow around the aircraft). Position error makes the altimeter always under-read.","s":"Nav 18","ch":"Altimeter","sec":"Errors — \"BLIP PBT\"","h":"chapters/nav-18.html#n-errors-blip-pbt"},{"t":"P — Pressure","d":"high → low pressure: reads higher than actual; low → high: reads lower than actual.","s":"Nav 18","ch":"Altimeter","sec":"Errors — \"BLIP PBT\"","h":"chapters/nav-18.html#n-errors-blip-pbt"},{"t":"Parallels of latitude","d":"small circles parallel to the equator (the equator is the only parallel that is a great circle); they cut every meridian at 90° → rhumb lines.","s":"Nav 2","ch":"The Earth","sec":"Latitude","h":"chapters/nav-02.html#n-latitude"},{"t":"Parts of the day (IST)","d":"early hours 0000–0400 · morning 0400–0800 · forenoon 0800–1200 · afternoon 1200–1600 · evening 1600–2000 · night 2000–2400.","s":"Met 30","ch":"Appendices: Scales, Terms and Monsoon Drivers","sec":"D. Miscellaneous terms","h":"chapters/met-30.html#n-d-miscellaneous-terms"},{"t":"Pitot tube","d":"senses impact (ram) air pressure; mounted where there is minimum disturbance, usually near the wing leading edge, piped to the back of the ASI case. Susceptible to dirt, water and ice — aircraft for instrument flight must have a heated pitot tube; inspect the tube and test the heater before flight. Its opening is nearly perpendicular to the relative wind.","s":"Nav 17","ch":"Air Data Systems","sec":"The pitot-static system","h":"chapters/nav-17.html#n-the-pitot-static-system"},{"t":"Planck's law","d":"distribution of radiated energy with wavelength (right-skewed curve).","s":"Met 3","ch":"Temperature","sec":"Insolation and radiation laws (p.30)","h":"chapters/met-03.html#n-insolation-and-radiation-laws-p-30"},{"t":"Polar cell (60–90°)","d":"air sinks and warms at the poles → polar high; surface outflow turned west → polar easterlies; meets warm subtropical air at the polar front (with the polar front jet).","s":"Met 20","ch":"General Circulation","sec":"Three-cell model (p.188–190)","h":"chapters/met-20.html#n-three-cell-model-p-188-190"},{"t":"Polar front","d":"between polar easterlies and mid-latitude westerlies (~60°), active in segments. Arctic front: between arctic and polar air. Mediterranean front: Pc Europe vs Tc N Africa (winter).","s":"Met 14","ch":"Air Masses, Fronts and WDs","sec":"Occlusions and others (p.134–135)","h":"chapters/met-14.html#n-occlusions-and-others-p-134-135"},{"t":"Polar orbiting","d":"650–1500 km; whole earth twice in 24 h, same place every 12 h (e.g. NOAA).","s":"Met 22","ch":"Weather Radar and Met Satellites","sec":"Met satellites (p.210–213)","h":"chapters/met-22.html#n-met-satellites-p-210-213"},{"t":"Position error","d":"varies with aircraft type and external configuration; flight tests plot it against airspeed, altitude and configuration, and the manufacturer builds a correcting circuit for the static signal → calibrated airspeed, actual TAS, calibrated altitude, true Mach. So a CADC is tailored to one aircraft type and not usable in others.","s":"Nav 17","ch":"Air Data Systems","sec":"CADC errors (common to all instruments)","h":"chapters/nav-17.html#n-cadc-errors-common-to-all-instruments"},{"t":"Potential (convective) instability","d":"a whole layer lifted bodily becomes unstable because latent heat released at its moist bottom steepens its lapse rate; needs high RH low down, low RH higher up.","s":"Met 9","ch":"Stability and Instability","sec":"Stability criteria (p.89)","h":"chapters/met-09.html#n-stability-criteria-p-89"},{"t":"Pressure","d":"Sahara–Siberia high belt centred 45°N 105°E; India on its southern edge: high over N India, low over the Indian Ocean; ~4 isobars 1012–1018 hPa; shallow trough Kerala–Gujarat along the west coast; shallow ridge over the Gangetic plains.","s":"Met 19","ch":"Climatology of India","sec":"Winter (Jan–Feb) (p.171–173)","h":"chapters/met-19.html#n-winter-jan-feb-p-171-173"},{"t":"Pressure","d":"transition; temperature rising, pressure falling; weak gradient — only two isobars (1006, 1008 hPa) parallel to the coast; peninsular trough along 78°E (79°E near Chennai by May); weak low over Pakistan (upper Sindh), weak trough E UP/Bihar; low over Myanmar; closed high over the east-central Bay west of the Bay Islands.","s":"Met 19","ch":"Climatology of India","sec":"Summer / pre-monsoon (Mar–May) (p.173–175)","h":"chapters/met-19.html#n-summer-pre-monsoon-mar-may-p-173-175"},{"t":"Pressure","d":"low over Baluchistan (994 hPa); monsoon trough Sriganganagar – Allahabad – Kolkata – head Bay; high over the S hemisphere at 30°S 60°E; seven isobars (994–1008 hPa); steep gradient along the west coast; shallow lows over Arunachal and Myanmar.","s":"Met 19","ch":"Climatology of India","sec":"SW monsoon (Jun–Sep) (p.175–180)","h":"chapters/met-19.html#n-sw-monsoon-jun-sep-p-175-180"},{"t":"Pressure","d":"flat; one isobar (1010 hPa) encloses India; monsoon trough moves to the Bay along 13°N; weak lows off Chennai and over Baluchistan.","s":"Met 19","ch":"Climatology of India","sec":"Post-monsoon / NE monsoon (Oct–Dec) (p.180–182)","h":"chapters/met-19.html#n-post-monsoon-ne-monsoon-oct-dec-p-180-182"},{"t":"Pressure","d":"QNH rounded down to whole hPa (996.6 → Q0996; 999.9 → Q0999); inches reported exactly (A3005). World range 850–1100 hPa.","s":"Met 25","ch":"METAR, SPECI and TREND","sec":"Reporting rules","h":"chapters/met-25.html#n-reporting-rules"},{"t":"Pressure altitude","d":"altimeter reading with 1013.2 hPa set (written 3500, 19000; as FL35, FL190).","s":"Met 2","ch":"Atmospheric Pressure","sec":"Altimetry definitions (p.17)","h":"chapters/met-02.html#n-altimetry-definitions-p-17"},{"t":"Pressure altitude","d":"altitude in the standard atmosphere corresponding to the pressure at that point. Constant flight level = constant outside pressure.","s":"Nav 18","ch":"Altimeter","sec":"From the questions","h":"chapters/nav-18.html#n-from-the-questions"},{"t":"Pressure gradient","d":"horizontal rate of change of pressure perpendicular to isobars, from high to low. Close isobars = steep gradient (strong wind); far apart = weak/flat.","s":"Met 2","ch":"Atmospheric Pressure","sec":"Pressure gradient, tendency, isallobars (p.16–17)","h":"chapters/met-02.html#n-pressure-gradient-tendency-isallobars-p-16-17"},{"t":"Pressure gradient force (PGF)","d":"from high to low, = pressure difference ÷ distance between isobars.","s":"Met 6","ch":"Winds","sec":"Coriolis (geostrophic) force (p.48)","h":"chapters/met-06.html#n-coriolis-geostrophic-force-p-48"},{"t":"Pressure systems","d":"lows/cyclones (ascent), anticyclones (descent).","s":"Met 8","ch":"Vertical Motion and Clouds","sec":"Vertical motion (p.75–76)","h":"chapters/met-08.html#n-vertical-motion-p-75-76"},{"t":"Pressure tendency","d":"change of pressure with time: 24 h in India, 3 h in higher latitudes.","s":"Met 2","ch":"Atmospheric Pressure","sec":"Pressure gradient, tendency, isallobars (p.16–17)","h":"chapters/met-02.html#n-pressure-gradient-tendency-isallobars-p-16-17"},{"t":"Primary bow","d":"radius 42°; red outside, violet inside.","s":"Met 10","ch":"Optical Phenomena","sec":"Rainbow (p.95–96)","h":"chapters/met-10.html#n-rainbow-p-95-96"},{"t":"PROB30 / PROB40","d":"30% or 40% probability. Change period 1809/1812 = 18th between 0900 and 1200 UTC.","s":"Met 26","ch":"TAF, ARFOR and ROFOR","sec":"TAF — Aerodrome Forecast (p.242–244)","h":"chapters/met-26.html#n-taf-aerodrome-forecast-p-242-244"},{"t":"QFE","d":"pressure at the aerodrome datum → altimeter reads height above the aerodrome/threshold.","s":"Nav 10","ch":"DR Elements: Pressure and Altimetry","sec":"Altimeter settings and altitudes","h":"chapters/nav-10.html#n-altimeter-settings-and-altitudes"},{"t":"QFF","d":"QFE reduced to MSL using the actual temperature (met charts).","s":"Nav 10","ch":"DR Elements: Pressure and Altimetry","sec":"Altimeter settings and altitudes","h":"chapters/nav-10.html#n-altimeter-settings-and-altitudes"},{"t":"QNH","d":"QFE reduced to MSL using ISA → reads altitude (AMSL); shows elevation on the ground.","s":"Nav 10","ch":"DR Elements: Pressure and Altimetry","sec":"Altimeter settings and altitudes","h":"chapters/nav-10.html#n-altimeter-settings-and-altitudes"},{"t":"Quantitative radar (10 cm)","d":"rate, total and intensity of precipitation, snowfall.","s":"Met 22","ch":"Weather Radar and Met Satellites","sec":"Wavelength bands (Table 22.1)","h":"chapters/met-22.html#n-wavelength-bands-table-22-1"},{"t":"Radiation","d":"needs no medium and does not heat the medium; solar radiation heats the earth directly. Radiation plays the most significant role in atmospheric heat transfer.","s":"Met 3","ch":"Temperature","sec":"Heat transfer (p.29–30)","h":"chapters/met-03.html#n-heat-transfer-p-29-30"},{"t":"Rain intensity (per day)","d":"trace 0.01–0.04 mm · light 2.5–7.5 mm · heavy 64.5–124.4 mm · very heavy 124.5–244.4 mm · rainy day ≥ 2.5 mm · mainly dry = very light rain · dry day = no rain.","s":"Met 30","ch":"Appendices: Scales, Terms and Monsoon Drivers","sec":"D. Miscellaneous terms","h":"chapters/met-30.html#n-d-miscellaneous-terms"},{"t":"Rain shadow","d":"lee side of a range, e.g. areas east of the Western Ghats.","s":"Met 11","ch":"Precipitation","sec":"Diurnal and seasonal variation (p.104)","h":"chapters/met-11.html#n-diurnal-and-seasonal-variation-p-104"},{"t":"Rainy day","d":"≥ 2.5 mm in a day.","s":"Met 11","ch":"Precipitation","sec":"Snow, sleet and terms (p.104)","h":"chapters/met-11.html#n-snow-sleet-and-terms-p-104"},{"t":"Range","d":"limited by attenuation by rain and earth curvature. Detect up to 500 km; resolution better up to 250 km. Normally echoes within 25 NM displayed; long-range echoes up to 75 NM also used.","s":"Met 22","ch":"Weather Radar and Met Satellites","sec":"Weather radar (p.206)","h":"chapters/met-22.html#n-weather-radar-p-206"},{"t":"Rate of descent","d":"height to lose ÷ time (e.g. FL290 → FL80 over 50 NM at 243 kt: 21 000 ft in 12.3 min ≈ 1700 ft/min).","s":"Nav 9","ch":"Dead Reckoning","sec":"Time and DR position","h":"chapters/nav-09.html#n-time-and-dr-position"},{"t":"Ravine winds","d":"pressure difference across hills drives strong flow through narrow valleys, continuing beyond the mouth.","s":"Met 6","ch":"Winds","sec":"Local winds (p.55–58)","h":"chapters/met-06.html#n-local-winds-p-55-58"},{"t":"Recovery factor","d":"fraction of the full ram rise a probe senses (0.75 sensing 5 °C → full rise 6.7 °C).","s":"Nav 11","ch":"DR Elements: Temperature and Airspeed","sec":"SAT and TAT","h":"chapters/nav-11.html#n-sat-and-tat"},{"t":"Red/Magenta","d":"heavy precipitation, TS, hail, strong winds, tornadoes, severe turbulence — always avoid.","s":"Met 22","ch":"Weather Radar and Met Satellites","sec":"Airborne weather radar (p.209)","h":"chapters/met-22.html#n-airborne-weather-radar-p-209"},{"t":"Relative humidity (RH)","d":"actual WV ÷ maximum possible at the same temperature and pressure × 100 = HMR/HMRsat × 100 = e/SVP × 100.","s":"Met 5","ch":"Humidity","sec":"Terms (p.41–42)","h":"chapters/met-05.html#n-terms-p-41-42"},{"t":"Relief","d":"contours (lines of equal elevation; approximate = form lines), spot heights, layer tinting, hachuring, hill shading.","s":"Nav 3","ch":"Projections","sec":"Scale","h":"chapters/nav-03.html#n-scale"},{"t":"Repetitive flight plan (RPL)","d":"for a series of frequently recurring, regularly operated IFR flights with identical basic features, submitted by an operator for retention and repetitive use by ATS.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Definitions (Annex 2 / Doc 4444)","h":"chapters/nav-16.html#n-definitions-annex-2-doc-4444"},{"t":"Reversal above 8 km","d":"because the equatorial troposphere is deeper, above ~8 km the poles are warmer than the equator (reversal of temperature and density).","s":"Met 1","ch":"Atmosphere","sec":"Tropopause details (p.5–6)","h":"chapters/met-01.html#n-tropopause-details-p-5-6"},{"t":"Reynolds number RN = ρ V l / μ","d":"ratio of inertial to viscous forces (dimensionless). A model and a full-size aircraft at the same RN behave the same aerodynamically.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Viscosity and Reynolds number (2-8)","h":"chapters/hb-01.html#n-viscosity-and-reynolds-number-2-8"},{"t":"Rhumb line (loxodrome)","d":"cuts all meridians at the same angle → constant track; not the shortest distance; spirals towards the nearer pole. Equator is the only line that is both GC and rhumb line (meridians are GCs and also rhumb lines of 000/180 — the book counts the equator).","s":"Nav 2","ch":"The Earth","sec":"Great circle, small circle, rhumb line","h":"chapters/nav-02.html#n-great-circle-small-circle-rhumb-line"},{"t":"Ridge","d":"wedge from a high; rounded (not V) isobars; fair weather; winds veer.","s":"Met 2","ch":"Atmospheric Pressure","sec":"Pressure patterns (p.21–22) (isobars at 2 hPa)","h":"chapters/met-02.html#n-pressure-patterns-p-21-22-isobars-at-2-hpa"},{"t":"RMI","d":"compass card slaved to the gyro-magnetic compass; the needle head reads the QDM directly.","s":"Nav 13","ch":"In-flight Navigation","sec":"Fixes and position lines","h":"chapters/nav-13.html#n-fixes-and-position-lines"},{"t":"Roaring Forties / Furious Fifties / Crying Sixties","d":"westerlies 35°–60° (stormy beyond 40°S).","s":"Met 6","ch":"Winds","sec":"Named winds (p.61–62)","h":"chapters/met-06.html#n-named-winds-p-61-62"},{"t":"ROBEX","d":"METAR/SPECI of international aerodromes and alternates exchanged outside India; AIREPs too.","s":"Met 21","ch":"Met Services for Aviation","sec":"Exchange of met messages (p.201)","h":"chapters/met-21.html#n-exchange-of-met-messages-p-201"},{"t":"ROFOR","d":"route forecast (coded): upper winds/temps, sig weather, cloud, freezing level, turbulence, icing, jet, tropopause, max wind.","s":"Met 21","ch":"Met Services for Aviation","sec":"Aviation forecasts (p.197–199)","h":"chapters/met-21.html#n-aviation-forecasts-p-197-199"},{"t":"Roll cloud","d":"cylindrical, appears to roll; behind the first gust, detached from the CB; seldom severe.","s":"Met 13","ch":"Thunderstorms","sec":"Life cycle (p.114–116)","h":"chapters/met-13.html#n-life-cycle-p-114-116"},{"t":"Rossby (planetary) waves","d":"giant meanders (troughs and ridges) of upper westerlies in a rotating atmosphere/ocean (discovered by Carl Rossby, 1930s); the meandering jet streams are Rossby waves; strongly influence weather.","s":"Met 20","ch":"General Circulation","sec":"Standing and Rossby waves (p.191–192)","h":"chapters/met-20.html#n-standing-and-rossby-waves-p-191-192"},{"t":"Rotation","d":"seen from above the North Pole anticlockwise (west → east); from above the South Pole clockwise. The earth spins about its polar diameter (axis).","s":"Nav 2","ch":"The Earth","sec":"Shape and size","h":"chapters/nav-02.html#n-shape-and-size"},{"t":"Rotor streaming","d":"strong low-level wind that weakens/reverses aloft → violent rotors on the lee slope.","s":"Met 16","ch":"CAT and Mountain Waves","sec":"Vertical currents and clouds (p.150–151)","h":"chapters/met-16.html#n-vertical-currents-and-clouds-p-150-151"},{"t":"RRR","d":"1 = trace, 2 = 0.1–0.9 (book table), … the book's question uses 2 → 1.6–2.4 mm.","s":"Met 24","ch":"Station Models","sec":"Codes","h":"chapters/met-24.html#n-codes"},{"t":"Runway Visual Range","d":"range over which a pilot on the runway centre line can see the runway markings or the lights delineating the runway / its centre line.","s":"Met 7","ch":"Visibility and Fog","sec":"RVR (p.67–68)","h":"chapters/met-07.html#n-rvr-p-67-68"},{"t":"S-band (10 cm)","d":"cyclone detection radar; X-band (3 cm) = airborne and storm detection.","s":"Met 22","ch":"Weather Radar and Met Satellites","sec":"Exam traps","h":"chapters/met-22.html#n-exam-traps"},{"t":"Saffir–Simpson","d":"Cat 1 minimal > 980 hPa, 64–83 kt, surge 4–5 ft · Cat 2 moderate 965–979, 84–96 kt, 6–8 ft · Cat 3 extensive 945–964, 97–113 kt, 9–12 ft · Cat 4 extreme 920–944, 114–135 kt, 13–18 ft · Cat 5 catastrophic < 920 hPa, > 135 kt, > 18 ft.","s":"Met 30","ch":"Appendices: Scales, Terms and Monsoon Drivers","sec":"B. Meteorological scales","h":"chapters/met-30.html#n-b-meteorological-scales"},{"t":"SAR (still air range)","d":"fuel available × TAS ÷ FC.","s":"Nav 12","ch":"PNR, PET and Range","sec":"Point of no return (PNR / PSR / radius of action)","h":"chapters/nav-12.html#n-point-of-no-return-pnr-psr-radius-of-action"},{"t":"SAT / OAT / true air temperature / ambient","d":"the temperature of the undisturbed air.","s":"Nav 11","ch":"DR Elements: Temperature and Airspeed","sec":"SAT and TAT","h":"chapters/nav-11.html#n-sat-and-tat"},{"t":"Saturated air","d":"holds the maximum WV (like a full sponge).","s":"Met 5","ch":"Humidity","sec":"Terms (p.41–42)","h":"chapters/met-05.html#n-terms-p-41-42"},{"t":"Saturation HMR","d":"maximum HMR at that temperature and pressure; rises with temperature.","s":"Met 5","ch":"Humidity","sec":"Terms (p.41–42)","h":"chapters/met-05.html#n-terms-p-41-42"},{"t":"Saturation vapour pressure (SVP)","d":"vapour pressure when saturated.","s":"Met 5","ch":"Humidity","sec":"Terms (p.41–42)","h":"chapters/met-05.html#n-terms-p-41-42"},{"t":"Scale (instrument) error","d":"tied to a particular set of altitude aneroids, varies with altitude; plotted for each CADC and reduced with a corrective camshaft on the altitude output.","s":"Nav 17","ch":"Air Data Systems","sec":"CADC errors (common to all instruments)","h":"chapters/nav-17.html#n-cadc-errors-common-to-all-instruments"},{"t":"Scale effect","d":"change of aerodynamic characteristics with RN. A 1/10 model has 1/10 the length, 1/100 the area and 1/1000 the mass; to match RN the \"VL law\" would need 10× the speed (a 400 km/h aircraft → 4000 km/h in the tunnel). Raising the tunnel air density 25× keeps RN the same at only 160 km/h.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Viscosity and Reynolds number (2-8)","h":"chapters/hb-01.html#n-viscosity-and-reynolds-number-2-8"},{"t":"Scheduled flights","d":"printed/electronic plans accepted; the operator obtains ATS, COMM and MET briefing and keeps the documents as records for 6 months. ATC may still require the PIC/crew to report in person for special briefing.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"India: filing flight plans","h":"chapters/nav-16.html#n-india-filing-flight-plans"},{"t":"Scopes","d":"PPI (Plan Position Indicator) = plan view, gives bearing and range; RHI (Range Height Indicator) = direct reading of heights of CB cells.","s":"Met 22","ch":"Weather Radar and Met Satellites","sec":"Weather radar (p.206)","h":"chapters/met-22.html#n-weather-radar-p-206"},{"t":"Screen height","d":"imaginary screen at the end of TODR and start of LDR (35 ft). PMC = power management computer; QRH = quick reference handbook.","s":"Nav 15","ch":"Performance","sec":"Terms","h":"chapters/nav-15.html#n-terms"},{"t":"Sea breeze (day)","d":"land heats → air rises → pressure aloft over land rises → upper air drifts seaward → surface pressure rises over sea, falls over land → sea-to-land wind.","s":"Met 6","ch":"Winds","sec":"Sea and land breeze (p.57–58)","h":"chapters/met-06.html#n-sea-and-land-breeze-p-57-58"},{"t":"Secondary bow","d":"radius about 52° (red inside at 50°, violet outside at 54°); fainter, about twice as broad.","s":"Met 10","ch":"Optical Phenomena","sec":"Rainbow (p.95–96)","h":"chapters/met-10.html#n-rainbow-p-95-96"},{"t":"Section 1","d":"area AAAAA, visibility VVVV, weather W1W1W1, cloud groups NsCChshshs (e.g. 2AC100 = 2/8 AC at 10 000 ft; layer rules 1/8, 3/8, 5/8, plus CB), 7hfhfhf freezing level, 6IchihihitL icing, 5BhBhBhBtL turbulence, 4hxhxhxTT dddff wind & temperature, 2h'ph'pTpTp tropopause.","s":"Met 26","ch":"TAF, ARFOR and ROFOR","sec":"ARFOR — Area Forecast (p.247–249)","h":"chapters/met-26.html#n-arfor-area-forecast-p-247-249"},{"t":"Segment 1","d":"from 35 ft at V2 to gear fully retracted. Segment 2: gear up to at least 400 ft at V2 — the performance-limiting segment. Segment 3 (transition): level acceleration for flap/slat retraction. Final segment: to at least 1500 ft, clean, maximum continuous power, final climb speed.","s":"Nav 15","ch":"Performance","sec":"Take-off flight path and segments","h":"chapters/nav-15.html#n-take-off-flight-path-and-segments"},{"t":"Sensible horizon","d":"horizon through the observer without refraction (what a spirit level senses); lies above the visible horizon. Visible horizon: lowered by refraction.","s":"Nav 1","ch":"The Solar System","sec":"Horizon and twilight","h":"chapters/nav-01.html#n-horizon-and-twilight"},{"t":"Sensors","d":"measure the surrounding atmosphere: all systems use a pitot tube, static ports and a temperature probe; complex ones add an angle-of-attack sensor.","s":"Nav 17","ch":"Air Data Systems","sec":"Air data system","h":"chapters/nav-17.html#n-air-data-system"},{"t":"Severe","d":"almost continuous thunder and lightning, heavy rain/showers, maybe hail; wind > 40 kt.","s":"Met 13","ch":"Thunderstorms","sec":"Intensity (p.117)","h":"chapters/met-13.html#n-intensity-p-117"},{"t":"Severe TS","d":"locally damaging winds, frequent lightning, or large hail.","s":"Met 13","ch":"Thunderstorms","sec":"What it is (p.112)","h":"chapters/met-13.html#n-what-it-is-p-112"},{"t":"Severe-storm signatures","d":"intense, sharp echoes (strong updraughts; anvil = fuzzy top); hooks, appendages, protuberances → hail; \"figure 6\" echo → tornado; rapidly moving echoes → strong winds; slanting rain columns → vertical wind shear; dry holes (echo-free areas inside extensive bright echo) → strong winds and heavy rain; rapidly developing, large horizontal, converging echoes → severe storm; bright band (a few hundred m thick, just bel…","s":"Met 22","ch":"Weather Radar and Met Satellites","sec":"Cloud echoes (p.208–209)","h":"chapters/met-22.html#n-cloud-echoes-p-208-209"},{"t":"Shear line","d":"in the same air mass wind speed falls sharply S → N (or vice versa); friction → small-scale ascent; if deep → thick ST, AS, NS up to ~500 km across; with a fresh surge, CU/CB embedded at its leading edge.","s":"Met 18","ch":"Tropical Systems","sec":"Surge and shear line (p.157–158)","h":"chapters/met-18.html#n-surge-and-shear-line-p-157-158"},{"t":"Shear line","d":"line/zone of abrupt change in horizontal wind component (maximum horizontal shear). Wind discontinuity: line of abrupt change in wind direction.","s":"Met 30","ch":"Appendices: Scales, Terms and Monsoon Drivers","sec":"A. Synoptic systems","h":"chapters/met-30.html#n-a-synoptic-systems"},{"t":"Shelf cloud","d":"wedge-shaped with flat base, at the gust front, attached to the CB; associated with severe weather.","s":"Met 13","ch":"Thunderstorms","sec":"Life cycle (p.114–116)","h":"chapters/met-13.html#n-life-cycle-p-114-116"},{"t":"Sidereal day","d":"between two transits of a fixed star / the First Point of Aries = 23 h 56 min.","s":"Nav 1","ch":"The Solar System","sec":"Year and day","h":"chapters/nav-01.html#n-year-and-day"},{"t":"Single cell","d":"one updraught; rarely severe; summer heating (or winter cold fronts).","s":"Met 13","ch":"Thunderstorms","sec":"Classification by structure (p.113)","h":"chapters/met-13.html#n-classification-by-structure-p-113"},{"t":"Small circle","d":"any circle on the surface that is not a GC.","s":"Nav 2","ch":"The Earth","sec":"Great circle, small circle, rhumb line","h":"chapters/nav-02.html#n-great-circle-small-circle-rhumb-line"},{"t":"Somali jet","d":"low-level (1–1.5 km) cross-equatorial flow reaching jet speed along the E coast of Africa; from near Mauritius/N Madagascar; reaches India's W coast in June, strongest in July; stronger jet → stronger monsoon.","s":"Met 30","ch":"Appendices: Scales, Terms and Monsoon Drivers","sec":"G. Other systems influencing the SW monsoon","h":"chapters/met-30.html#n-g-other-systems-influencing-the-sw-monsoon"},{"t":"Source regions","d":"where air stagnates over a uniform surface — high-pressure areas with slack gradients and light winds: the poles and the subtropical highs.","s":"Met 14","ch":"Air Masses, Fronts and WDs","sec":"Air masses (p.129–130)","h":"chapters/met-14.html#n-air-masses-p-129-130"},{"t":"SPECI","d":"special report — immediately for deterioration; for improvement after 10 min once conditions stabilise; TREND appended.","s":"Met 21","ch":"Met Services for Aviation","sec":"Observations and reports","h":"chapters/met-21.html#n-observations-and-reports"},{"t":"Special features","d":"e.g. \"A WD lies over W Rajasthan with upper-air cyclonic circulation up to 20 000 ft\".","s":"Met 29","ch":"Flight Forecast: Tabular and Cross-Section","sec":"Met T-3 — tabular flight forecast (sample, Table 29.1)","h":"chapters/met-29.html#n-met-t-3-tabular-flight-forecast-sample-table-29-1"},{"t":"Specific heat","d":"heat needed to raise unit mass by 1°C. Water 1 (highest), ice 0.5, soil 0.2 → land heats and cools much faster than water. Temperature rise is inversely proportional to specific heat.","s":"Met 3","ch":"Temperature","sec":"Definitions (p.28)","h":"chapters/met-03.html#n-definitions-p-28"},{"t":"Spot wind/temperature chart","d":"forecast wind and temperature at grid points for several altitudes (e.g. 30 280100 −32 = 30 000 ft, 280°/100 kt, −32 °C) plus the freezing level.","s":"Met 30","ch":"Appendices: Scales, Terms and Monsoon Drivers","sec":"F. Met charts","h":"chapters/met-30.html#n-f-met-charts"},{"t":"Squall","d":"sudden increase of ≥ 16 kt (32 km/h, 8 m/s), reaching ≥ 22 kt (44 km/h, 11 m/s), lasting ≥ 1 minute. With CB / violent convection; spreads several km and thousands of feet; direction and speed differ widely from the prevailing wind; often a sharp temperature drop and precipitation.","s":"Met 6","ch":"Winds","sec":"Gust, lull, squall, gale (p.46–47)","h":"chapters/met-06.html#n-gust-lull-squall-gale-p-46-47"},{"t":"Squall","d":"usually up to 40 kt, can be 100 kt; strongest ahead of the storm.","s":"Met 13","ch":"Thunderstorms","sec":"Hazards (p.117–120)","h":"chapters/met-13.html#n-hazards-p-117-120"},{"t":"St Elmo's fire","d":"bluish/greenish glow with crackling on an aircraft in CU/CB from a strong electric field; weak to moderate.","s":"Met 10","ch":"Optical Phenomena","sec":"Atmospheric electricity and lightning (p.99–100)","h":"chapters/met-10.html#n-atmospheric-electricity-and-lightning-p-99-100"},{"t":"Stable","d":"a displaced parcel returns (ball in a bowl). Unstable: keeps going (ball on an upturned bowl). Neutral: stays where put.","s":"Met 9","ch":"Stability and Instability","sec":"Stability ideas (p.88–89)","h":"chapters/met-09.html#n-stability-ideas-p-88-89"},{"t":"Standard masses","d":"crew 85 kg (75 + 10), adult 75 kg, child (2–12) 35 kg, infant (< 2) 10 kg (training flights may use actual crew masses). Scales calibrated as required.","s":"Nav 14","ch":"Mass and Balance","sec":"Weighing and records (India)","h":"chapters/nav-14.html#n-weighing-and-records-india"},{"t":"Standard time","d":"time set by the legal authorities for a country or part of it, kept on a chosen meridian. IST = UTC + 5 h 30 min (82°30′E); IST and LMT agree only at 82°30′E.","s":"Nav 5","ch":"Time","sec":"Basics","h":"chapters/nav-05.html#n-basics"},{"t":"Standing (stationary) wave","d":"two waves of equal amplitude and frequency moving in opposite directions; in the atmosphere = month/season-averaged deviations of the circulation caused by mountains, continents, oceans, SST contrasts; N/S flows carry heat and moisture, alter storm tracks.","s":"Met 20","ch":"General Circulation","sec":"Standing and Rossby waves (p.191–192)","h":"chapters/met-20.html#n-standing-and-rossby-waves-p-191-192"},{"t":"Static (barometric) pressure","d":"air at rest; molecules in random motion push equally in all directions.","s":"Met 2","ch":"Atmospheric Pressure","sec":"Static and dynamic pressure (p.12)","h":"chapters/met-02.html#n-static-and-dynamic-pressure-p-12"},{"t":"Static port","d":"usually flush on the side of the fuselage, sensing the pressure of the still air; vents on both sides compensate for erratic static changes with attitude. Its opening is always parallel to the relative airflow.","s":"Nav 17","ch":"Air Data Systems","sec":"The pitot-static system","h":"chapters/nav-17.html#n-the-pitot-static-system"},{"t":"Static pressure (S)","d":"the weight of the air acting on every surface; higher at lower altitude.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Density and pressures (2-5)","h":"chapters/hb-01.html#n-density-and-pressures-2-5"},{"t":"Stationary front","d":"barely moves; winds parallel to it in opposite directions on either side (e.g. polar front).","s":"Met 14","ch":"Air Masses, Fronts and WDs","sec":"Occlusions and others (p.134–135)","h":"chapters/met-14.html#n-occlusions-and-others-p-134-135"},{"t":"Statute mile","d":"5280 ft = 0.87 NM (1 NM = 1.15 SM). NM > SM > km.","s":"Nav 7","ch":"Distances on the Earth","sec":"Units","h":"chapters/nav-07.html#n-units"},{"t":"Steady streamline flow","d":"properties may differ from point to point but stay constant in time at any point; streamlines follow the surface and never cross. Unsteady flow cannot be drawn as streamlines.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Streamline flow and lift theories (2-6 to 2-7)","h":"chapters/hb-01.html#n-streamline-flow-and-lift-theories-2-6-to-2-7"},{"t":"Steady-state TS","d":"fronts, converging winds, troughs aloft force ascent; precipitation falls outside the updraught; lasts several hours.","s":"Met 13","ch":"Thunderstorms","sec":"Types (p.112–113)","h":"chapters/met-13.html#n-types-p-112-113"},{"t":"Steaming fog (sea smoke)","d":"cold air over a warm sea; vapour from the warm water condenses in the cold air. High latitudes, frozen land, Iceland, Norway.","s":"Met 7","ch":"Visibility and Fog","sec":"Other fogs (p.72)","h":"chapters/met-07.html#n-other-fogs-p-72"},{"t":"Stefan–Boltzmann law","d":"total energy radiated ∝ T⁴ (absolute temperature) → hot bodies (sun) emit intense radiation.","s":"Met 3","ch":"Temperature","sec":"Insolation and radiation laws (p.30)","h":"chapters/met-03.html#n-insolation-and-radiation-laws-p-30"},{"t":"Stopway","d":"prepared area beyond TORA for stopping after a rejected take-off; at least as wide as the runway, able to bear the aircraft. Counts only in ASDA.","s":"Nav 15","ch":"Performance","sec":"Declared distances","h":"chapters/nav-15.html#n-declared-distances"},{"t":"Stratiform cloud / steady rain","d":"diffuse, ill-defined, uniform-intensity echoes; on RHI a bright band at the freezing level (strong reflection from melting snowflakes) — seen only with weak, uniform updraughts; vanishes as convection increases.","s":"Met 22","ch":"Weather Radar and Met Satellites","sec":"Cloud echoes (p.208–209)","h":"chapters/met-22.html#n-cloud-echoes-p-208-209"},{"t":"Supercell","d":"separate up/downdraughts (vertical wind shear) and a rotating updraught (mesocyclone); can reach the lower stratosphere; hail up to 10 cm, winds > 130 km/h, flash floods; most tornadoes; up to 24 km wide.","s":"Met 13","ch":"Thunderstorms","sec":"Classification by structure (p.113)","h":"chapters/met-13.html#n-classification-by-structure-p-113"},{"t":"Superior (upper) mirage","d":"over snow fields, cold sea → inversion.","s":"Met 10","ch":"Optical Phenomena","sec":"Mirage (p.97)","h":"chapters/met-10.html#n-mirage-p-97"},{"t":"Supplementary","d":"RE recent weather (RERA, RETS); WS RWY09 / WS ALL RWY wind shear; sea temperature and state W19/S4; runway state; RMK remarks.","s":"Met 25","ch":"METAR, SPECI and TREND","sec":"Reporting rules","h":"chapters/met-25.html#n-reporting-rules"},{"t":"Surface temperature","d":"measured 1.25 m (4 ft) above the ground in shade, inside a Stevenson screen (door opens away from the sun).","s":"Met 3","ch":"Temperature","sec":"Definitions (p.28)","h":"chapters/met-03.html#n-definitions-p-28"},{"t":"Surface winds","d":"March — W north of 17°N, E south; April — N–NW to E UP and east to NE India; May — SW over Rajasthan, E from E UP to NE India, S over Odisha/WB/Bihar/Jharkhand/Chhattisgarh. Dust-raising winds over the Gangetic plains 0900–1700 h.","s":"Met 19","ch":"Climatology of India","sec":"Summer / pre-monsoon (Mar–May) (p.173–175)","h":"chapters/met-19.html#n-summer-pre-monsoon-mar-may-p-173-175"},{"t":"Surface winds","d":"E–SE north of the trough, SW–W elsewhere (more southerly over WB; NW on the Malabar coast); 5–10 kt over land, ~15 kt at sea; monsoon strength depends on these.","s":"Met 19","ch":"Climatology of India","sec":"SW monsoon (Jun–Sep) (p.175–180)","h":"chapters/met-19.html#n-sw-monsoon-jun-sep-p-175-180"},{"t":"Surge (pulse)","d":"sudden strengthening of the wind within the same air mass; air arrives faster than it leaves → velocity convergence → ascent, CU, showers, squalls. Common over the Arabian Sea in the monsoon: ~40 kt behind (west of) the surge line vs 10–15 kt ahead. Moves with the wind to the head Bay; activates the ITCZ, favours depressions.","s":"Met 18","ch":"Tropical Systems","sec":"Surge and shear line (p.157–158)","h":"chapters/met-18.html#n-surge-and-shear-line-p-157-158"},{"t":"Symmetric aerofoil","d":"CP stays at about 25% chord whatever the AoA.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Centre of pressure and aerodynamic centre (2-10)","h":"chapters/hb-01.html#n-centre-of-pressure-and-aerodynamic-centre-2-10"},{"t":"Systems","d":"STJ, 5–7 WDs/month in the north; a few cyclones and easterly waves in the south.","s":"Met 19","ch":"Climatology of India","sec":"Winter (Jan–Feb) (p.171–173)","h":"chapters/met-19.html#n-winter-jan-feb-p-171-173"},{"t":"T — Temperature","d":"high → low temperature: altimeter over-reads (H-L-H). Calibrated to ISA temperature and pressure lapse rate; no altimeter setting compensates for temperature deviation. At constant indicated altitude from warm to cold air the aircraft descends and is truly lower than indicated. \"Hot to cold, don't be bold\" / \"cold kills\". The opposite from cold to hot.","s":"Nav 18","ch":"Altimeter","sec":"Errors — \"BLIP PBT\"","h":"chapters/nav-18.html#n-errors-blip-pbt"},{"t":"T (Dvorak CI) numbers","d":"Low T1.5, D T2.0, DD T2.5, CS T3.0, SCS T3.5, VSCS T4.0–6.0, SuCS T6.5–8.0.","s":"Met 30","ch":"Appendices: Scales, Terms and Monsoon Drivers","sec":"B. Meteorological scales","h":"chapters/met-30.html#n-b-meteorological-scales"},{"t":"TAF","d":"by AMOs for own and associated AMSs; valid min 9 h, max 30 h. 9-h TAFs every 3 h; 12–30 h TAFs every 6 h, from 0000 UTC.","s":"Met 21","ch":"Met Services for Aviation","sec":"Aviation forecasts (p.197–199)","h":"chapters/met-21.html#n-aviation-forecasts-p-197-199"},{"t":"Take-off alternate","d":"to land shortly after take-off if the departure aerodrome cannot be used.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Definitions (Annex 2 / Doc 4444)","h":"chapters/nav-16.html#n-definitions-annex-2-doc-4444"},{"t":"Take-off forecast","d":"within 3 h before ETD: surface wind (2-min mean), temperature, QNH, others.","s":"Met 21","ch":"Met Services for Aviation","sec":"Aviation forecasts (p.197–199)","h":"chapters/met-21.html#n-aviation-forecasts-p-197-199"},{"t":"Taper ratio","d":"Ct / Cr. Aspect ratio = span / mean chord = b² / S.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Definitions (2-9)","h":"chapters/hb-01.html#n-definitions-2-9"},{"t":"Tc","d":"most common over India, especially winter; from the Siberian high; cold, dry, fair weather, poor visibility. Over NW India in summer.","s":"Met 14","ch":"Air Masses, Fronts and WDs","sec":"Air masses over India (p.130–131)","h":"chapters/met-14.html#n-air-masses-over-india-p-130-131"},{"t":"TCU","d":"light to severe up to at least the −20°C level.","s":"Met 12","ch":"Ice Accretion","sec":"Icing by cloud (p.108)","h":"chapters/met-12.html#n-icing-by-cloud-p-108"},{"t":"TEET (total estimated elapsed time)","d":"IFR — from take-off to that approach point (or over the destination aerodrome if no navaid); VFR — from take-off to over the destination aerodrome.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Definitions (Annex 2 / Doc 4444)","h":"chapters/nav-16.html#n-definitions-annex-2-doc-4444"},{"t":"Temperate latitudes","d":"depressions and fronts → maximum in winter. NW India / J&K / western Himalaya follow this because of Western Disturbances (occluded fronts, frequent in winter).","s":"Met 11","ch":"Precipitation","sec":"Diurnal and seasonal variation (p.104)","h":"chapters/met-11.html#n-diurnal-and-seasonal-variation-p-104"},{"t":"Temperature","d":"Dec–Jan coldest; mean minimum 22°C far south → 10°C northern plains → 6°C Punjab; diurnal range ~13°C (10°C coasts, 5°C Tamil Nadu).","s":"Met 19","ch":"Climatology of India","sec":"Winter (Jan–Feb) (p.171–173)","h":"chapters/met-19.html#n-winter-jan-feb-p-171-173"},{"t":"Temperature","d":"central peninsula 30–35°C in April; mean max 40–42°C; hottest in May (Andamans April, Saurashtra June, Rajasthan & Kashmir July). Max diurnal range 18°C (Gujarat, Saurashtra, MP); ~6°C on coasts. Heat wave: ≥ 4–5°C above normal maximum.","s":"Met 19","ch":"Climatology of India","sec":"Summer / pre-monsoon (Mar–May) (p.173–175)","h":"chapters/met-19.html#n-summer-pre-monsoon-mar-may-p-173-175"},{"t":"Temperature","d":"south ~26°C, Rajasthan ~31°C; spatial range ~9°C, diurnal 4–9°C; rises in breaks.","s":"Met 19","ch":"Climatology of India","sec":"SW monsoon (Jun–Sep) (p.175–180)","h":"chapters/met-19.html#n-sw-monsoon-jun-sep-p-175-180"},{"t":"Temperature","d":"nearly uniform ~18°C; diurnal range 6–7°C; NW India mean falls from ~38°C (Oct) to 28°C (Nov).","s":"Met 19","ch":"Climatology of India","sec":"Post-monsoon / NE monsoon (Oct–Dec) (p.180–182)","h":"chapters/met-19.html#n-post-monsoon-ne-monsoon-oct-dec-p-180-182"},{"t":"Temperature","d":"x.5 rounded up: +2.5 → 03, −2.5 → M02; e.g. 24/M02.","s":"Met 25","ch":"METAR, SPECI and TREND","sec":"Reporting rules","h":"chapters/met-25.html#n-reporting-rules"},{"t":"Temperature increasing with height","d":"negative lapse rate → stability, no turbulence.","s":"Met 9","ch":"Stability and Instability","sec":"Inversion (p.88)","h":"chapters/met-09.html#n-inversion-p-88"},{"t":"Terrain","d":"rises on the windward side, sinks on the lee; strong winds → mountain (lee) waves; can carry WV into the stratosphere → nacreous clouds.","s":"Met 8","ch":"Vertical Motion and Clouds","sec":"Vertical motion (p.75–76)","h":"chapters/met-08.html#n-vertical-motion-p-75-76"},{"t":"Terrestrial radiation","d":"long-wave, invisible, mostly IR. Earth gains heat as short wave and loses it as long wave.","s":"Met 3","ch":"Temperature","sec":"Solar, terrestrial and nocturnal radiation (p.31)","h":"chapters/met-03.html#n-solar-terrestrial-and-nocturnal-radiation-p-31"},{"t":"Thermal","d":"heat the air above its dew point (WW2 FIDO burners; costly, discontinued).","s":"Met 7","ch":"Visibility and Fog","sec":"Fog dispersal (p.72)","h":"chapters/met-07.html#n-fog-dispersal-p-72"},{"t":"Thermal wind","d":"the vector that must be added to the lower-level geostrophic wind to give the upper-level geostrophic wind = upper − lower (vertical wind shear).","s":"Met 6","ch":"Winds","sec":"Thermal wind (p.58–59)","h":"chapters/met-06.html#n-thermal-wind-p-58-59"},{"t":"Thickness","d":"height difference between two pressure levels: low where the layer is cold, high where warm; thickness lines = isotherms of mean layer temperature.","s":"Met 2","ch":"Atmospheric Pressure","sec":"Contours and thickness (p.16)","h":"chapters/met-02.html#n-contours-and-thickness-p-16"},{"t":"Tibetan High","d":"warm anticyclone at 300 hPa over the Tibetan plateau (~28°N 98°E), 70–110°E; its easterly outflow feeds the TEJ (13–15°N near Chennai, 150 hPa, July), running from Vietnam to W Africa; accelerates S China Sea → S India, decelerates beyond. Shifts E/W vary monsoon activity; a far-west shift can push the monsoon into Pakistan/N Iran.","s":"Met 30","ch":"Appendices: Scales, Terms and Monsoon Drivers","sec":"G. Other systems influencing the SW monsoon","h":"chapters/met-30.html#n-g-other-systems-influencing-the-sw-monsoon"},{"t":"Tm","d":"from the N Pacific subtropical high via SE Asia in the monsoon; hot, humid, high dew point; excellent visibility; fair diurnal range; CU with showers/TS. Over NE India and along the Himalaya in summer.","s":"Met 14","ch":"Air Masses, Fronts and WDs","sec":"Air masses over India (p.130–131)","h":"chapters/met-14.html#n-air-masses-over-india-p-130-131"},{"t":"TORA","d":"runway available for the ground run. TODA = TORA + clearway. ASDA = TORA + stopway. LDA: runway for landing, reduced by a displaced threshold (affects only landings towards that threshold).","s":"Nav 15","ch":"Performance","sec":"Declared distances","h":"chapters/nav-15.html#n-declared-distances"},{"t":"Tornado","d":"rotating funnel sucked up into a CB base; winds > 150 kt; core pressure drop of hundreds of hPa (condensation makes it visible); diameter metres to ~200 m; life minutes to over an hour; narrow path of devastation; hook-shaped radar echo; rare in India (New Delhi, April 1978). Fujita scale (Appendix B).","s":"Met 13","ch":"Thunderstorms","sec":"Tornado, waterspout, dust devil (p.124–125)","h":"chapters/met-13.html#n-tornado-waterspout-dust-devil-p-124-125"},{"t":"Track (TR)","d":"path over the ground, normally °T. Required track (RT): wanted; Track made good (TMG): actually flown (join the start and a fix).","s":"Nav 9","ch":"Dead Reckoning","sec":"Terms","h":"chapters/nav-09.html#n-terms"},{"t":"Track error (TE)","d":"angle from required track to TMG; starboard/port likewise; TMG = RT ± TE.","s":"Nav 9","ch":"Dead Reckoning","sec":"Triangle of velocities","h":"chapters/nav-09.html#n-triangle-of-velocities"},{"t":"Trades","d":"steady winds 10°–30°, NE in NH, SE in SH.","s":"Met 6","ch":"Winds","sec":"Named winds (p.61–62)","h":"chapters/met-06.html#n-named-winds-p-61-62"},{"t":"Traffic load (payload)","d":"passengers, baggage, cargo (incl. non-revenue). Useful load = traffic load + usable fuel = TOM − DOM.","s":"Nav 14","ch":"Mass and Balance","sec":"Mass terms","h":"chapters/nav-14.html#n-mass-terms"},{"t":"Transducers","d":"convert pressure, temperature and angles to voltages, synchro outputs or digital pulses; their accuracy governs the whole system.","s":"Nav 17","ch":"Air Data Systems","sec":"Air data system","h":"chapters/nav-17.html#n-air-data-system"},{"t":"Transition altitude (TA)","d":"altitude at or below which you fly on QNH (vertical position as altitude).","s":"Met 2","ch":"Atmospheric Pressure","sec":"Altimetry definitions (p.17)","h":"chapters/met-02.html#n-altimetry-definitions-p-17"},{"t":"Transition layer","d":"airspace between TA and TL.","s":"Met 2","ch":"Atmospheric Pressure","sec":"Altimetry definitions (p.17)","h":"chapters/met-02.html#n-altimetry-definitions-p-17"},{"t":"Transition level (TL)","d":"lowest flight level available above TA; above it you fly on 1013.2 hPa. Expressed in hundreds of feet.","s":"Met 2","ch":"Atmospheric Pressure","sec":"Altimetry definitions (p.17)","h":"chapters/met-02.html#n-altimetry-definitions-p-17"},{"t":"Transverse","d":"cylinder tangent along a chosen meridian and its anti-meridian. Conformal; scale correct along the datum meridian, expanding as sec (GC distance from it). Convergence correct at the equator and poles. Straight lines at 90° to the datum meridian are GCs; meridians and parallels are complex curves (parallels ellipses).","s":"Nav 3","ch":"Projections","sec":"Transverse and oblique Mercator","h":"chapters/nav-03.html#n-transverse-and-oblique-mercator"},{"t":"TREND (landing forecast)","d":"appended to METAR/SPECI by AMOs (except Jaipur and Safdarjung); valid 2 h; PROB not used; NOSIG = no significant change.","s":"Met 21","ch":"Met Services for Aviation","sec":"Aviation forecasts (p.197–199)","h":"chapters/met-21.html#n-aviation-forecasts-p-197-199"},{"t":"Tropics","d":"convective → rain mostly in the afternoon; summer > winter.","s":"Met 11","ch":"Precipitation","sec":"Diurnal and seasonal variation (p.104)","h":"chapters/met-11.html#n-diurnal-and-seasonal-variation-p-104"},{"t":"Tropopause and max-wind chart","d":"tropopause FL in boxes (e.g. FL400); jet path as bold arrows with FL; 0 °C isotherm as short dashes.","s":"Met 30","ch":"Appendices: Scales, Terms and Monsoon Drivers","sec":"F. Met charts","h":"chapters/met-30.html#n-f-met-charts"},{"t":"Trough","d":"tongue/V-shaped extension of a low; pressure lower than either side; wind changes abruptly and backs; bad weather. Example: monsoon trough over the Indo-Gangetic plains.","s":"Met 2","ch":"Atmospheric Pressure","sec":"Pressure patterns (p.21–22) (isobars at 2 hPa)","h":"chapters/met-02.html#n-pressure-patterns-p-21-22-isobars-at-2-hpa"},{"t":"Trough in the easterlies / easterly wave","d":"shallow trough in the tropical easterlies moving E → W, clearer in upper winds than in surface pressure; cloud and showers; affects S peninsular India.","s":"Met 30","ch":"Appendices: Scales, Terms and Monsoon Drivers","sec":"A. Synoptic systems","h":"chapters/met-30.html#n-a-synoptic-systems"},{"t":"Trough in the westerlies","d":"mid-latitude wave moving W → E; affects northern India.","s":"Met 30","ch":"Appendices: Scales, Terms and Monsoon Drivers","sec":"A. Synoptic systems","h":"chapters/met-30.html#n-a-synoptic-systems"},{"t":"Troughs in westerlies","d":"upper-air waves moving W → E with divergence ahead; when behind a surface system, they enhance weather: severe TS/DS, Nor'westers, heavy rain.","s":"Met 14","ch":"Air Masses, Fronts and WDs","sec":"Fronts in India and Western Disturbances (p.136–137)","h":"chapters/met-14.html#n-fronts-in-india-and-western-disturbances-p-136-137"},{"t":"True direction (°T)","d":"measured from true north (towards the geographic pole, the earth's spin axis). A line drawn on a map shows a true direction.","s":"Nav 6","ch":"Compass and Directions","sec":"Three norths","h":"chapters/nav-06.html#n-three-norths"},{"t":"TS gust front","d":"cold outflow meets warm air; reaches ~30 km ahead and ~6,000 ft up.","s":"Met 6","ch":"Winds","sec":"Wind shear (p.54–55)","h":"chapters/met-06.html#n-wind-shear-p-54-55"},{"t":"Turning errors","d":"max turning onto/through N/S, nil on E/W. Turning through the nearer pole the compass is sluggish (undershoot) → roll out early; through the equator it is lively (overshoot) → roll out late. (\"APPS\")","s":"Nav 8","ch":"Magnetism and Compasses","sec":"Errors due to dip (direct-reading compass)","h":"chapters/nav-08.html#n-errors-due-to-dip-direct-reading-compass"},{"t":"Twilight colours","d":"refraction, scattering, selective absorption at sunrise/sunset.","s":"Met 10","ch":"Optical Phenomena","sec":"Other phenomena (p.97–98)","h":"chapters/met-10.html#n-other-phenomena-p-97-98"},{"t":"Ultra-sensitive radar","d":"convection before/after cloud forms; CAT, gravity waves, lee waves.","s":"Met 22","ch":"Weather Radar and Met Satellites","sec":"Wavelength bands (Table 22.1)","h":"chapters/met-22.html#n-wavelength-bands-table-22-1"},{"t":"Upper winds","d":"to ~10,000 ft NW (north/central) and NE (south); westerlies above, strengthening with height, reaching the tip of the peninsula; STJ ~12 km, 27°N, 80–100 kt (max 200).","s":"Met 19","ch":"Climatology of India","sec":"Winter (Jan–Feb) (p.171–173)","h":"chapters/met-19.html#n-winter-jan-feb-p-171-173"},{"t":"Upper winds","d":"westerlies strengthen with height (April 40 kt at 300 hPa, 60 kt at 200 hPa north of 22°N); in May the westerly belt moves to 30°N and 15–20 kt easterlies set in over the peninsula; June: westerlies to 700 hPa, easterlies above south of 25°N (50 kt at 100 hPa).","s":"Met 19","ch":"Climatology of India","sec":"Summer / pre-monsoon (Mar–May) (p.173–175)","h":"chapters/met-19.html#n-summer-pre-monsoon-mar-may-p-173-175"},{"t":"Upper winds","d":"to ~10,000 ft W–SW south of the trough, SE north of it; easterlies from 500 hPa up over almost all India; anticyclones over Tibet and Baluchistan at 200 hPa; TEJ at 15–16 km, 70–80 kt (max 150) along ~13°N.","s":"Met 19","ch":"Climatology of India","sec":"SW monsoon (Jun–Sep) (p.175–180)","h":"chapters/met-19.html#n-sw-monsoon-jun-sep-p-175-180"},{"t":"Upper winds","d":"westerlies re-establish; STJ reappears over J&K; easterlies above 500 hPa only in the far south (~20 kt).","s":"Met 19","ch":"Climatology of India","sec":"Post-monsoon / NE monsoon (Oct–Dec) (p.180–182)","h":"chapters/met-19.html#n-post-monsoon-ne-monsoon-oct-dec-p-180-182"},{"t":"Upslope fog","d":"moist air lifted up a slope, cooling adiabatically.","s":"Met 7","ch":"Visibility and Fog","sec":"Other fogs (p.72)","h":"chapters/met-07.html#n-other-fogs-p-72"},{"t":"Vapour pressure (e)","d":"partial pressure of WV; pressure of dry air = p − e.","s":"Met 5","ch":"Humidity","sec":"Terms (p.41–42)","h":"chapters/met-05.html#n-terms-p-41-42"},{"t":"Variable gases","d":"water vapour, CO, SO₂, NO₂, methane — more over industrial areas, cities, water bodies; tiny in amount but very significant for weather and life.","s":"Met 1","ch":"Atmosphere","sec":"Variable gases and greenhouse gases (p.2)","h":"chapters/met-01.html#n-variable-gases-and-greenhouse-gases-p-2"},{"t":"Variation (magnetic declination)","d":"angle between true and magnetic north. Magnetic north east of true = easterly (+); west = westerly (−). Changes from place to place (and with mineral deposits); given on maps and charts.","s":"Nav 6","ch":"Compass and Directions","sec":"Variation and deviation","h":"chapters/nav-06.html#n-variation-and-deviation"},{"t":"Vector","d":"magnitude and direction. Scalar: magnitude only.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Physical terms (2-3)","h":"chapters/hb-01.html#n-physical-terms-2-3"},{"t":"VFR → IFR","d":"if a flight plan was filed, pass the changes to the current plan; or, when required, submit a flight plan and get a clearance before proceeding IFR in controlled airspace.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Changing flight rules","h":"chapters/nav-16.html#n-changing-flight-rules"},{"t":"Virga","d":"precipitation falling from a cloud that evaporates before reaching the ground.","s":"Met 8","ch":"Vertical Motion and Clouds","sec":"The ten genera (p.79–80)","h":"chapters/met-08.html#n-the-ten-genera-p-79-80"},{"t":"Virtual temperature","d":"the temperature at which dry air would have the same pressure and density as the moist air parcel (lets the dry-air equation of state be used for moist air).","s":"Met 3","ch":"Temperature","sec":"Definitions (p.28)","h":"chapters/met-03.html#n-definitions-p-28"},{"t":"Viscosity (μ)","d":"resistance to relative motion between adjacent fluid layers; for air 1.79 × 10⁻⁵ kg/m/s at ISA MSL. In a gas it rises with temperature (more molecular collisions), so it falls with height to the tropopause and stays steady above. In a liquid it falls with temperature.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Viscosity and Reynolds number (2-8)","h":"chapters/hb-01.html#n-viscosity-and-reynolds-number-2-8"},{"t":"Visibility steps","d":"50 m for 0–800 m; 100 m for 800–5000 m; 1 km for 5000–9000 m; 9999 = 10 km or more. Directional: 6000S; if minimum < 1500 m and another direction > 5000 m report both, e.g. 1400SW 6000E.","s":"Met 25","ch":"METAR, SPECI and TREND","sec":"Reporting rules","h":"chapters/met-25.html#n-reporting-rules"},{"t":"Visual checkpoint","d":"big enough to see, small enough to pinpoint, unique. Coastlines (inlets, piers better than straight beaches), rivers/lakes (change with seasons, floods, drought, snow), hills (look flatter from higher; may be in cloud), villages (cross-check), towns (shape + roads/railways), cities (too large to fix accurately), railways and roads (line features: along track for tracking, across track for timing; junctions and bri…","s":"Nav 13","ch":"In-flight Navigation","sec":"Visual navigation (map reading)","h":"chapters/nav-13.html#n-visual-navigation-map-reading"},{"t":"VOLMET","d":"met information for aircraft in flight, broadcast on a published schedule, 5-min slots per station on one HF/VHF frequency. D-VOLMET (data link): METAR, SPECI, 9-h TAF, SIGMET, special AIREPs, AIRMET. Voice VOLMET in India on HF from Mumbai and Kolkata in turn every half hour — Mumbai: METARs of Mumbai, Ahmedabad, Chennai, Colombo, Karachi, Male; TAFs of Mumbai, Male, Colombo. Kolkata: METARs of Kolkata, Delhi, Dh…","s":"Met 21","ch":"Met Services for Aviation","sec":"Exchange of met messages (p.201)","h":"chapters/met-21.html#n-exchange-of-met-messages-p-201"},{"t":"VOR","d":"on an RMI or an OBI (TO flag = QDM, FROM flag = QDR); convert with variation at the station (constant for that VOR); plot as QTE from the station's true meridian.","s":"Nav 13","ch":"In-flight Navigation","sec":"Fixes and position lines","h":"chapters/nav-13.html#n-fixes-and-position-lines"},{"t":"VSI transonic jump","d":"near Mach 1 a shock wave makes the static pressure drop as it passes the static source → a brief false jump on the VSI (a positive sign the aircraft is close to the speed of sound).","s":"Nav 17","ch":"Air Data Systems","sec":"Errors specific to the ASI and VSI","h":"chapters/nav-17.html#n-errors-specific-to-the-asi-and-vsi"},{"t":"VV","d":"90 < 50 m, 91 50–<200, 92 200–<500, 93 500–<1000, 94 1–<2 km, 95 2–<4 km, 96 4–<10 km, 97 10–<20 km, 98 20–<50 km, 99 ≥ 50 km.","s":"Met 24","ch":"Station Models","sec":"Codes","h":"chapters/met-24.html#n-codes"},{"t":"W/V","d":"direction the wind blows from / speed, e.g. 330/25.","s":"Nav 9","ch":"Dead Reckoning","sec":"Terms","h":"chapters/nav-09.html#n-terms"},{"t":"W1W2","d":"0 cloud < 4/8, 1 > 4/8 part period, 2 > 4/8 throughout, 3 DS, 4 FG, 5 DZ, 6 RA, 7 SN, 8 SH, 9 TS.","s":"Met 24","ch":"Station Models","sec":"Codes","h":"chapters/met-24.html#n-codes"},{"t":"WAFS (World Area Forecast System)","d":"gives Met Offices global en-route forecasts (upper winds and temperatures). Two WAFCs: Washington and London. 19 RAFCs (Regional Area Forecast Centres), one at New Delhi.","s":"Met 21","ch":"Met Services for Aviation","sec":"Purpose and organisations (p.194–195)","h":"chapters/met-21.html#n-purpose-and-organisations-p-194-195"},{"t":"Wake","d":"SUPER (book prints S; the ICAO code is J, e.g. A380); /H HEAVY ≥ 136 000 kg MTOM; /M MEDIUM < 136 000 kg but > 7 000 kg; /L LIGHT ≤ 7 000 kg.","s":"Nav 16","ch":"Flight Planning and Monitoring","sec":"Item 9 — Number, type, wake category","h":"chapters/nav-16.html#n-item-9-number-type-wake-category"},{"t":"Warm occlusion","d":"air behind less cold than the air ahead → rides over the warm front; warm-front-type weather; winter, less common.","s":"Met 14","ch":"Air Masses, Fronts and WDs","sec":"Occlusions and others (p.134–135)","h":"chapters/met-14.html#n-occlusions-and-others-p-134-135"},{"t":"Wash-in","d":"twist that increases incidence towards the tip. Wash-out: twist that decreases incidence towards the tip.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Definitions (2-9)","h":"chapters/hb-01.html#n-definitions-2-9"},{"t":"Waterspout","d":"tornado over the sea (can cause \"rain of fish\").","s":"Met 13","ch":"Thunderstorms","sec":"Tornado, waterspout, dust devil (p.124–125)","h":"chapters/met-13.html#n-tornado-waterspout-dust-devil-p-124-125"},{"t":"WD","d":"low or trough moving W → E, north of 20°N, causing weather. Two or more closed isobars (2 hPa) = Western Depression. Upper troughs above 500 hPa = troughs in westerlies.","s":"Met 14","ch":"Air Masses, Fronts and WDs","sec":"Fronts in India and Western Disturbances (p.136–137)","h":"chapters/met-14.html#n-fronts-in-india-and-western-disturbances-p-136-137"},{"t":"Weather","d":"north — clear, dry, poor visibility, low humidity and temperature, broken by WDs: winds back NW → SW/SE, temperature rises, pressure falls, CI → AS, NS, ST, drizzle/rain (warm-front type), then CU/CB, pressure rise, TS (cold-front type); then clear, cold dry N–NW winds, widespread radiation fog and cold waves (temperature ≥ 4°C below normal minimum, lasting 2–3 days). Cold day: maximum ≤ 16°C in the plains. Cold w…","s":"Met 19","ch":"Climatology of India","sec":"Winter (Jan–Feb) (p.171–173)","h":"chapters/met-19.html#n-winter-jan-feb-p-171-173"},{"t":"Weather","d":"widespread dust haze and very high temperatures; dust storms over N/NW India, Nor'westers (Kalbaishakhi) over E and NE India, triggered by WDs; a few cyclones hit Bengal; STJ weakens and moves north.","s":"Met 19","ch":"Climatology of India","sec":"Summer / pre-monsoon (Mar–May) (p.173–175)","h":"chapters/met-19.html#n-summer-pre-monsoon-mar-may-p-173-175"},{"t":"Weather","d":"1–2 WDs/month in the north; best flying season (except S India): clear skies, good visibility. Maximum cyclones: October in the Bay, November in the Arabian Sea; SCS more in November; usually from the Andaman Sea towards TN/AP/Odisha; some recurve to WB/Bangladesh; some cross into the Arabian Sea and hit Maharashtra/Gujarat.","s":"Met 19","ch":"Climatology of India","sec":"Post-monsoon / NE monsoon (Oct–Dec) (p.180–182)","h":"chapters/met-19.html#n-post-monsoon-ne-monsoon-oct-dec-p-180-182"},{"t":"Weather","d":"onset/cessation/intensity change of FZ precipitation, FZFG, moderate/heavy precipitation, drifting/blowing snow, sand, dust, DS, SS, TS, squall, funnel cloud.","s":"Met 25","ch":"METAR, SPECI and TREND","sec":"SPECI criteria (p.230–231) — deterioration at once, improvement after 10 min","h":"chapters/met-25.html#n-speci-criteria-p-230-231-deterioration-at-once-improvement-after-10-min"},{"t":"Weather abbreviations","d":"DZ, RA, SN, SG, PL/PE ice pellets, IC ice crystals, GR hail ≥ 5 mm, GS small hail < 5 mm, FG, BR, SA, DU, HZ, FU, VA, PO dust devil, SQ, FC funnel cloud, DS, SS, SH, TS.","s":"Met 25","ch":"METAR, SPECI and TREND","sec":"Reporting rules","h":"chapters/met-25.html#n-reporting-rules"},{"t":"Western disturbance (WD)","d":"surface low or mid/lower-tropospheric cyclonic circulation/trough from the Mediterranean, Caspian and Black Seas, moving across N India; with ≥ 2 closed isobars = western depression.","s":"Met 30","ch":"Appendices: Scales, Terms and Monsoon Drivers","sec":"A. Synoptic systems","h":"chapters/met-30.html#n-a-synoptic-systems"},{"t":"Wet-bulb temperature","d":"lowest temperature air can reach by evaporating water into it until saturated (desert-cooler principle; drier air cools more).","s":"Met 5","ch":"Humidity","sec":"Wet bulb, dew point, frost point (p.42)","h":"chapters/met-05.html#n-wet-bulb-dew-point-frost-point-p-42"},{"t":"Wien's law","d":"wavelength of maximum radiation ∝ 1/T → hot sun emits short waves, cool earth emits long waves.","s":"Met 3","ch":"Temperature","sec":"Insolation and radiation laws (p.30)","h":"chapters/met-03.html#n-insolation-and-radiation-laws-p-30"},{"t":"Wind","d":"horizontal movement of air; a succession of gusts (strong) and lulls (weak). Two components: direction and speed.","s":"Met 6","ch":"Winds","sec":"Basics (p.45)","h":"chapters/met-06.html#n-basics-p-45"},{"t":"Wind","d":"27010KT. VRB when speed < 3 kt (VRB02KT), or at higher speed when direction varies ≥ 180° (VRB10KT). Calm (< 1 kt) 00000KT. Gust 30020G40KT. Extreme directions 270V050 only when variation 60°–180° and wind ≥ 3 kt. ≥ 100 kt: P99KT (240100KT → 240P99KT).","s":"Met 25","ch":"METAR, SPECI and TREND","sec":"Reporting rules","h":"chapters/met-25.html#n-reporting-rules"},{"t":"Wind","d":"direction change ≥ 60° with speed ≥ 10 kt before/after; mean speed change ≥ 10 kt; gust variation ≥ 10 kt with speed ≥ 15 kt. (Any one triggers.)","s":"Met 25","ch":"METAR, SPECI and TREND","sec":"SPECI criteria (p.230–231) — deterioration at once, improvement after 10 min","h":"chapters/met-25.html#n-speci-criteria-p-230-231-deterioration-at-once-improvement-after-10-min"},{"t":"Wind shear","d":"variation of wind vector along the aircraft's path that can displace it.","s":"Met 6","ch":"Winds","sec":"Wind shear (p.54–55)","h":"chapters/met-06.html#n-wind-shear-p-54-55"},{"t":"Wind shear","d":"vertical shear → eddies, turbulence; CAT near jet streams; amplified over mountains.","s":"Met 8","ch":"Vertical Motion and Clouds","sec":"Vertical motion (p.75–76)","h":"chapters/met-08.html#n-vertical-motion-p-75-76"},{"t":"Wind shear","d":"outflow up to ~2,000 ft; landing aircraft gets a headwind then a tailwind; wind can change 90° or more in a few hundred feet. Strong vertical wind shear is needed for a severe TS.","s":"Met 13","ch":"Thunderstorms","sec":"Hazards (p.117–120)","h":"chapters/met-13.html#n-hazards-p-117-120"},{"t":"Wind shear warning","d":"observed/expected wind shear up to 500 m (1600 ft) above the runway on approach, take-off, circling or the runway; topographic shear above 500 m also included; appended to METAR/SPECI in abbreviated plain language, e.g. WS WRNG MBST APCH RWY 30; pilot reports include aircraft type (WS WRNG B747 REPORTED MOD WS IN APCH RWY 28 AT 1000).","s":"Met 21","ch":"Met Services for Aviation","sec":"Warnings (p.200)","h":"chapters/met-21.html#n-warnings-p-200"},{"t":"Winds","d":"SW → NE by mid-October; NE winds pick up moisture over the Bay → rain on TN and parts of Kerala; light variable winds inland; sea breeze felt up to 160 km inland.","s":"Met 19","ch":"Climatology of India","sec":"Post-monsoon / NE monsoon (Oct–Dec) (p.180–182)","h":"chapters/met-19.html#n-post-monsoon-ne-monsoon-oct-dec-p-180-182"},{"t":"Wing loading","d":"weight / wing area. Load factor = lift / weight.","s":"Handbook 1","ch":"Aerodynamics Basics","sec":"Definitions (2-9)","h":"chapters/hb-01.html#n-definitions-2-9"},{"t":"Wing-tip trails","d":"short-lived; pressure drop at wing tips/propellers → adiabatic cooling.","s":"Met 8","ch":"Vertical Motion and Clouds","sec":"Condensation trails (p.83–84)","h":"chapters/met-08.html#n-condensation-trails-p-83-84"},{"t":"WINTEM","d":"forecast upper wind and temperature.","s":"Met 21","ch":"Met Services for Aviation","sec":"Aviation forecasts (p.197–199)","h":"chapters/met-21.html#n-aviation-forecasts-p-197-199"},{"t":"Withdrawal","d":"from Rajasthan ~1 Sep, NW India 15 Sep, almost all India by 15 Oct, replaced by the NE (winter) monsoon.","s":"Met 19","ch":"Climatology of India","sec":"SW monsoon (Jun–Sep) (p.175–180)","h":"chapters/met-19.html#n-sw-monsoon-jun-sep-p-175-180"},{"t":"Yellow","d":"moderate precipitation, very low visibility, moderate turbulence — avoid.","s":"Met 22","ch":"Weather Radar and Met Satellites","sec":"Airborne weather radar (p.209)","h":"chapters/met-22.html#n-airborne-weather-radar-p-209"}];